// Üretilen dosya: tool/ozgun/uret.py. Toplum ve Sosyal Bilimler · Kent sosyolojisi, göç kuramları, demografik dönüşüm ve çalışma sosyolojisi (kentleşme-kentlileşme, soylulaştırma, itici-çekici etmenler) (orta).
const ozSocialscience18Orta = <(String, String, List<String>, String)>[
  ('Bir ülkede kent nüfusunun toplam nüfus içindeki oranı hızla yükselirken kentlerde birincil cemaat bağlarının ve hemşehrilik ağlarının baskınlığını koruması hangi kavramsal ayrımla açıklanır?', 'Kentleşme hızının kentlileşme hızını aşması', ['Kentlileşmenin kentleşmeden önce tamamlanması', 'Soylulaştırmanın banliyöleşmeyi durdurması', 'Metropolleşmenin kırsal nüfusu artırması'], 'Demografik yığılma olan kentleşme hızla gerçekleşirken kültürel ve davranışsal uyum olan kentlileşme daha yavaş ilerleyebilir.'),
  ('Köyünden büyükşehre taşınan bir ailenin apartmanda yaşamasına rağmen komşuluk ilişkilerini yalnızca aynı köyden gelen akrabalarıyla sınırlaması ve kentsel sivil toplum kuruluşlarına katılmaması neye örnektir?', 'Mekânsal kentleşmeye rağmen sosyal kentlileşmenin eksik kalmasına', ['Sosyal kentlileşmenin ekonomik kentleşmeyi engellemesine', 'Soylulaştırma sürecinin birincil ilişkileri güçlendirmesine', 'Eşmerkezli çemberler modelinin kırsal alanda uygulanmasına'], 'Kentsel mekânda bulunmak demografik kentleşmeyi sağlasa da kentsel örgütlenme ve ikincil ilişkilere geçememek kentlileşme eksikliğidir.'),
  ('Kırdan göçü zorlayan tarım topraklarının miras yoluyla parçalanması, makineleşme ve kırsal işsizlik gibi etkenler göç kuramlarında hangi kavram grubunda ele alınır?', 'İtici faktörler', ['Çekici faktörler', 'İletici faktörler', 'Soylulaştırıcı faktörler'], 'Kırsal alandaki geçim zorlukları ve yapısal sorunlar bireyi köyden koparan itici faktörleri oluşturur.'),
  ('Gelişmekte olan ülkelerde sanayi üretimi ve istihdam kapasitesi artmadan kent nüfusunun hızla şişmesi durumunu tanımlamak için kent sosyolojisinde hangi kavram kullanılır?', 'Sahte (aşırı) kentleşme', ['Dengeli kentleşme', 'Tersine kentleşme', 'Kültürel kentlileşme'], 'Ekonomik kalkınma ve sanayileşme temeli olmaksızın gerçekleşen demografik yığılma sahte veya aşırı kentleşme olarak adlandırılır.'),
  ('Ferdinand Tönnies\'in toplumsal yapıları açıklarken kullandığı ve kır-kent karşılaştırmalarına temel oluşturan kavramsal ikilik aşağıdakilerden hangisidir?', 'Cemaat (Gemeinschaft) ve Cemiyet', ['Mekanik dayanışma ve Organik işbölümü', 'Merkez bölge ve Geçiş bölgesi', 'Altyapı kurumları ve Üstyapı kurumları'], 'Tönnies, geleneksel ve samimi bağlara dayalı topluluğu cemaat, rasyonel ve sözleşmesel kent toplumunu cemiyet olarak ayırmıştır.'),
  ('Émile Durkheim\'ın kentleşme ve nüfus yoğunluğunun artışıyla birlikte uzmanlaşmanın derinleştiği modern toplumlarda ortaya çıktığını belirttiği dayanışma türü hangisidir?', 'Organik dayanışma', ['Mekanik dayanışma', 'Birincil dayanışma', 'Hemşehri dayanışması'], 'İşbölümü ve farklılaşmış rollerin birbirine bağımlılığı üzerine kurulu modern kentsel bütünleşme organik dayanışmadır.'),
  ('Georg Simmel\'e göre metropol insanının dış dünyadan gelen aşırı ve sürekli değişen duyusal uyaranlar karşısında ruhsal bütünlüğünü korumak için geliştirdiği kayıtsızlık ve bıkkınlık tutumuna ne ad verilir?', 'Bezginlik', ['Yabancılaşma sendromu', 'Anomik intihar eğilimi', 'Kollektif bilinç coşkusu'], 'Simmel, metropoldeki sinirsel uyaran bombardımanına karşı bireyin tepki verme eşiğini yükselttiği bu savunma hâlini blasé tutumu olarak adlandırır.'),
  ('Georg Simmel\'in analizinde metropol insanının küçük kasaba insanına kıyasla olaylara duygularıyla değil "aklıyla" (zihniyle) tepki vermesinin temel nedeni nedir?', 'Hızla değişen izlenimlerin yarattığı sinirsel yoğunluğa karşı psikolojik bir koruma kalkanı oluşturmak', ['Kırsal alandaki geleneksel dinî törenlerin zihinsel faaliyetleri tamamen yasaklamış olması', 'Metropollerdeki eğitim kurumlarının duygusal sanat dallarını müfredattan çıkarması', 'Kent merkezlerindeki sanayi tesislerinin fiziksel emeğe olan ihtiyacı ortadan kaldırması'], 'Duygular derin ve kalıcı bağlara uygun olduğundan, metropolün anlık ve yoğun uyaranlarına karşı yüzeysel kalan zihin koruyucu işlev görür.'),
  ('Sabah işe giderken metroda binlerce insanla omuz omuza yolculuk yapan bir kentlinin kimseyle göz teması kurmaması ve çevresindeki olağandışı görüntülere tepkisiz kalması Simmel\'in hangi kavramıyla açıklanır?', 'İhtiyatlılık (rezerv) ve bezginlik tutumu', ['Birincil grup içi duygusal dayanışma', 'Soylulaştırma kaynaklı mekânsal yerinden edilme', 'Ekolojik istila ve ardıllık döngüsü'], 'Simmel, kalabalık içinde bireyin zihinsel alanını korumak için geliştirdiği mesafeli ve kayıtsız duruşu rezerv ve blasé kavramlarıyla açıklar.'),
  ('Simmel\'e göre küçük kasaba ve kırsal topluluklarla karşılaştırıldığında metropolün bireye sunduğu en büyük olumlu imkân aşağıdakilerden hangisidir?', 'Dar toplumsal çemberin sıkı denetiminden kurtularak bireysel özgürlük ve özerklik kazanması', ['Herkesin birbirini yakından tanıdığı sarsılmaz bir duygusal güvenlik ağı içinde yaşaması', 'Mesleki uzmanlaşma zorunluluğu olmadan kendi kendine yeten üretim yapabilmesi', 'Kamusal alanda hiçbir hukuki kurala veya zaman planlamasına bağlı kalmaması'], 'Simmel, küçük toplulukların kıskanç ve sınırlandırıcı gözetiminin aksine metropolün bireye benzersiz bir hareket ve kimlik özgürlüğü verdiğini belirtir.'),
  ('Simmel\'in metropolde "nesnel kültürün" (teknoloji, kurumlar, bilgi birikimi) "öznel kültürü" (bireyin içsel gelişimi) ezdiğini belirtmesi bireyde hangi tepkiyi doğurur?', 'Fark edilmek ve silinmemek için aşırı uçlarda giyim, tavır ve eksantriklik sergileme çabası', ['Tüm kentsel iletişim araçlarını reddederek kırsal komün yaşamına topluca göç etme eğilimi', 'Mesleki işbölümünden vazgeçerek her ürünü evde kendi elleriyle üretme arzusu', 'Mahalle muhtarlıkları etrafında sıkı bir geleneksel denetim mekanizması kurma isteği'], 'Devasa nesnel kültür karşısında önemsizleşen metropol bireyi, kendi biricikliğini kanıtlamak için abartılı farklılaşma arayışına girebilir.'),
  ('Ernest Burgess\'in Eşmerkezli Çemberler Kuramı\'nda kentin tam kalbinde (birinci halkada) yer alan bölge aşağıdakilerden hangisidir?', 'Merkezi İş Alanı', ['İşçi konutları bölgesi', 'Orta sınıf konut bölgesi', 'Banliyö ve uydu kent kuşağı'], 'Birinci çember (The Loop), bankaların, büyük mağazaların, ofislerin ve ulaşım hatlarının kesiştiği Merkezi İş Alanı\'dır.'),
  ('Burgess\'in Eşmerkezli Çemberler modelinde Merkezi İş Alanı\'nı hemen çevreleyen ikinci halka olan "Geçiş Bölgesi" (Zone in Transition) hangi özellikleriyle öne çıkar?', 'Eskimiş binalar, hafif sanayi, düşük kiralar, yeni göçmen yerleşimleri ve yüksek toplumsal çözülme oranlarıyla', ['Geniş bahçeli müstakil villalar, yüksek gelirli aileler ve düşük nüfus yoğunluğuyla', 'Yalnızca büyük tarım işletmeleri, ormanlık alanlar ve kırsal dinlenme tesisleriyle', 'Düzenli apartman bloklarında yaşayan vasıflı fabrika işçilerinin istikrarlı aile yaşamıyla'], 'Geçiş bölgesi, ticaret ve sanayinin yayılma baskısı altındaki köhneleşmiş yapılarıyla kente ilk gelen yoksul göçmenlerin tutunma alanıdır.'),
  ('Eşmerkezli Çemberler modelinde Geçiş Bölgesi\'ndeki kötü koşullardan kurtulabilen ancak fabrikalara yakın kalmak isteyen mavi yakalıların yerleştiği üçüncü çember hangisidir?', 'Bağımsız işçi konutları bölgesi', ['Merkezi ticaret ve finans alanı', 'Seçkin banliyö ve komütör kuşağı', 'Tarihi sit ve turizm koruma bölgesi'], 'Üçüncü halka, ikinci kuşak göçmenlerin ve sanayi işçilerinin yaşadığı mütevazı ama geçiş bölgesine göre daha düzenli konut alanıdır.'),
  ('Chicago Okulu temsilcilerinden Robert Ezra Park ve Roderick McKenzie\'nin bitki ve hayvan ekolojisinden ödünç alarak kentsel mekân değişimini açıkladıkları iki temel süreç nedir?', 'İstila ve ardıllık', ['Yabancılaşma ve şeyleşme', 'Soylulaştırma ve özelleştirme', 'Merkezileşme ve bürokratikleşme'], 'Kentsel ekolojide bir toplumsal grubun veya arazi kullanım biçiminin başka bir bölgeye sızması istila, oraya tamamen hâkim olması ardıllık olarak tanımlanır.'),
  ('Eskiden orta sınıf ailelerin yaşadığı kent merkezine yakın bir mahalleye zamanla atölyelerin ve yeni göçmenlerin girmesi, eski sakinlerin ise dış halkalara taşınması Chicago Okulu\'na göre neye örnektir?', 'Ekolojik istila ve ardıllık sürecine', ['Tersine soylulaştırma politikasına', 'Kamusal mekânın demokratikleşmesine', 'Kırsal cemaat yapısının korunmasına'], 'Yeni bir nüfus veya ekonomik işlevin alanı devralması ve önceki grubun daha dış çemberlere kayması klasik istila-ardıllık mekanizmasıdır.'),
  ('Louis Wirth\'in sosyolojik kent tanımında kentsel yaşam biçimini üreten üç temel değişken aşağıdakilerden hangisinde doğru verilmiştir?', 'Nüfus büyüklüğü, yoğunluk ve toplumsal heterojenlik', ['Tarımsal üretim fazlası, sur duvarları ve askerî garnizon', 'Sanayi bacası sayısı, belediye bütçesi ve otoyol uzunluğu', 'Tarihi eser varlığı, turizm geliri ve üniversite sayısı'], 'Wirth\'e göre kenti tanımlayan ve ikincil ilişkileri doğuran üç yapısal unsur büyük nüfus, yüksek yoğunluk ve toplumsal çeşitliliktir (heterojenlik).'),
  ('Louis Wirth\'e göre kentlerde nüfus büyüklüğü ve yoğunluğun artması kişilerarası toplumsal ilişkileri nasıl dönüştürür?', 'İlişkileri yüzeysel, anonim, geçici ve parçalı (segmente) ikincil ilişkilere dönüştürür', ['Komşuluk bağlarını güçlendirerek herkesin birbirini tüm kişiliğiyle tanımasını sağlar', 'Resmî hukuk kurallarına ve polis denetimine olan ihtiyacı tamamen ortadan kaldırır', 'Toplumsal işbölümünü azaltarak aile içi geleneksel üretimi yeniden egemen kılar'], 'Çok sayıda insanla temas etmek zorunda kalan kentli, insanlarla bütün kişilikleriyle değil yalnızca belirli rolleri (kasiyer, şoför, müşteri) üzerinden ilişki kurar.'),
  ('Burgess\'in dairesel modeline alternatif olarak 1939\'da Homer Hoyt tarafından geliştirilen ve kentin ana ulaşım aksları boyunca dilimler hâlinde büyüdüğünü savunan kuram hangisidir?', 'Sektör (Dilim) Kuramı', ['Çok Merkezli Kent Kuramı', 'Küresel Kent Hiyerarşisi Kuramı', 'Yaratıcı Sınıf ve Mekân Kuramı'], 'Homer Hoyt, konut kiraları ve sanayi alanlarının eşmerkezli halkalar yerine ulaşım koridorlarını izleyen kama/dilim (sektör) biçiminde yayıldığını göstermiştir.'),
  ('1945 yılında Chauncy Harris ve Edward Ullman tarafından geliştirilen, modern kentlerin tek bir merkez etrafında değil birden fazla uzmanlaşmış odak etrafında şekillendiğini savunan model hangisidir?', 'Çok Merkezli Kent Kuramı', ['Eşmerkezli Çemberler Kuramı', 'Kırsal Cazibe Merkezleri Kuramı', 'Tek Kutuplu Metropol Kuramı'], 'Harris ve Ullman, otomobil kullanımı ve uzmanlaşmayla birlikte üniversite, sanayi, havaalanı ve ticaret gibi birden çok çekirdeğin oluştuğunu açıklamıştır.'),
  ('Robert Ezra Park\'ın iki farklı kültürel dünyanın sınırında yaşayan, kırsal kökeninden kopmuş ancak kentsel egemen gruba da tam kabul edilmemiş göçmen tipini tanımladığı kavram hangisidir?', 'Marjinal insan', ['Kozmopolit seçkin', 'Organik aydın', 'Bürokratik uzman'], 'Park\'ın "marjinal insan" kavramı, iki kültür arasında kalarak kimlik gerilimi yaşayan ama aynı zamanda keskin bir gözlem gücü kazanan melez konumu anlatır.'),
  ('Türkiye\'de gecekondulaşma olgusunun kitlesel ölçekte başladığı ve büyük kentlerin çeperlerini sarmaya başladığı tarihsel dönem hangisidir?', 'İkinci Dünya Savaşı sonrası 1945-1950 yılları', ['Osmanlı Devleti\'nin Tanzimat Fermanı dönemi', 'Birinci Dünya Savaşı öncesi 1910\'lu yıllar', 'Cumhuriyetin ilanından hemen önceki 1920\'li yıllar'], 'Tarımda makineleşme, Marshall yardımları, karayolu ağının gelişmesi ve kırsal nüfus artışıyla 1940\'ların sonu ve 1950\'lerde kitlesel gecekondulaşma başlamıştır.'),
  ('Türkiye\'de erken dönem (1950-1970 arası) gecekondulaşmasının temel niteliği aşağıdakilerden hangisidir?', 'Göçmenlerin ticari ranttan ziyade kendi barınma ihtiyacını karşılamak üzere imece ve akraba dayanışmasıyla tek katlı konutlar yapması', ['Uluslararası inşaat şirketlerinin hazine arazileri üzerinde çok katlı lüks alışveriş merkezleri inşa etmesi', 'Devletin kırsal kesimden gelen her aileye kent merkezinde ücretsiz tapulu apartman dairesi tahsis etmesi', 'Kentteki yüksek gelirli grupların vergi ödememek için ormanlık alanlarda güvenlikli siteler kurması'], 'İlk kuşak gecekondular kullanım değerine odaklı, barınma sorununa halkın kendi imkânlarıyla ürettiği enformel çözümlerdi.'),
  ('Kemal Karpat ve Şerif Mardin gibi araştırmacıların erken dönem gecekondu araştırmalarında tespit ettikleri "tampon mekanizma" kavramı neyi ifade eder?', 'Akrabalık ve hemşehrilik ağlarının göçmenin kentte tutunmasını sağlayarak toplumsal sarsıntıyı yumuşatmasını', ['Belediyelerin gecekondu mahalleleri ile kent merkezi arasına yüksek beton duvarlar örmesini', 'Fabrika sahiplerinin işçilere sendikalaşmamaları karşılığında kırsal bölgelerde tarla bağışlamasını', 'Polis teşkilatının kente giriş noktalarında vize uygulaması başlatarak göçü engellemesini'], 'Tampon kurumlar (hemşehri dernekleri, aile bağları) ne tam kırsal ne tam kentsel olan yapılarıyla göçmenin kriz yaşamadan kente uyumuna aracılık eder.'),
  ('Latin Amerika ülkelerinde Türkiye\'deki gecekondu mahallelerine benzer biçimde kent çeperlerinde veya yamaçlarda oluşan enformel yerleşimlere verilen adlardan biri hangisidir?', 'Favela (Brezilya)', ['Banlieue (İsviçre)', 'Suburbia (Kanada)', 'Gentrification (İngiltere)'], 'Brezilya\'da favela, Peru\'da barriada, Arjantin\'de villa miseria gibi adlar alan yerleşimler küresel Güney\'deki enformel konut alanlarıdır.'),
  ('Sema Erder ve Tahire Erman gibi kent sosyologlarının Türkiye\'de 1990\'lar sonrasındaki gecekondu ve çeper mahalle çalışmalarında dikkat çektikleri "nöbetleşe yoksulluk" (Oğuz Işık - Melih Pınarcıoğlu) kavramı neyi anlatır?', 'Kente daha önce gelen göçmen grupların arsa rantı ve ilişkiler üzerinden tutunurken yükü yeni gelen daha dezavantajlı göçmenlere devretmesini', ['Kentteki tüm toplumsal sınıfların ekonomik kriz dönemlerinde eşit oranda gelir kaybına uğrayarak dayanışmasını', 'Belediyelerin her yıl farklı bir mahalleye sırayla altyapı hizmeti götürüp diğer mahallelerin suyunu kesmesini', 'Mevsimlik tarım işçilerinin yaz aylarında zenginleşip kış aylarında kent merkezindeki otellerde konaklamasını'], 'Nöbetleşe yoksulluk, önceki göçmen kuşaklarının enformel ağlar ve emlak artışı sayesinde yükselirken sonradan gelenlerin (ör. zorunlu göç mağdurlarının) altta kalmasını açıklar.'),
  ('Coğrafyacı Neil Smith\'in soylulaştırmayı arz yönlü ve ekonomik temelde açıklamak için geliştirdiği "rant farkı" (rent gap) kuramı neyi ifade eder?', 'Körelmiş bir kentsel arazinin mevcut düşük getirisi ile yeniden geliştirildiğinde sağlayacağı potansiyel en yüksek getiri arasındaki uçurumu', ['Kent merkezindeki dükkan kiraları ile kırsal bölgedeki tarım arazisi vergileri arasındaki yasal oran farkını', 'Belediyelerin toplu taşıma biletlerinden elde ettiği gelir ile park bakım giderleri arasındaki bütçe açığını', 'Kapalı sitelerde oturan kiracılar ile ev sahipleri arasında yönetim kurulunda yaşanan oy hakkı eşitsizliğini'], 'Neil Smith\'e göre binalar eskidikçe mevcut kira geliri düşer; potansiyel rant ile fiili rant arasındaki fark yeterince açıldığında sermaye bölgeye geri döner.'),
  ('David Ley gibi araştırmacıların soylulaştırmayı "talep yönlü" ve kültürel eksende açıklarken vurgu yaptıkları "yeni orta sınıf" profilinin temel özelliği nedir?', 'Banliyönün tekzepliğini reddederek tarihi dokuya, kültürel çeşitliliğe, sanata ve kent merkezindeki kafelere yakın yaşamayı arzulayan profesyoneller olmaları', ['Kent merkezindeki kalabalıktan kaçarak otoyol kenarındaki büyük alışveriş merkezlerinin yanına yerleşmek isteyen fabrika işçileri olmaları', 'Tarımsal üretime dönmek amacıyla kent merkezindeki binaları yıkıp kentsel bostanlar kuran emekli memurlar olmaları', 'Geleneksel geniş aile yapısını sürdürmek için yalnızca hemşehrilerinin yaşadığı çeper mahalleleri tercih eden esnaflar olmaları'], 'Kültürel yaklaşıma göre finans, medya, tasarım ve akademi alanındaki yeni orta sınıf, yaşam tarzı ve estetik beğeni üzerinden tarihi merkezlere yönelir.'),
  ('İstanbul\'da Cihangir, Kuzguncuk, Galata, Balat veya Ortaköy gibi semtlerde son on yıllarda eski konutların restore edilip sanat galerileri ve üçüncü nesil kahvecilerin açılmasıyla kiraların hızla yükselmesi hangi sürecin tipik örneğidir?', 'Soylulaştırma (gentrification)', ['Sahte kentleşme (over-urbanization)', 'Kırsal cemaatleşme (ruralization)', 'Ağır sanayileşme (industrialization)'], 'Türkiye\'de tarihi ve merkezi semtlerin orta-üst sınıf ve kültür endüstrisi tarafından dönüştürülmesi soylulaştırma literatürünün en bilinen örnekleridir.'),
  ('Soylulaştırma sürecinin toplumsal adalet açısından en çok eleştirilen sonucu olan "yerinden edilme" (displacement) ne anlama gelir?', 'Artan kiralar, emlak vergileri ve değişen mahalle esnafı nedeniyle dar gelirli eski sakinlerin ve kiracıların mahalleden ayrılmak zorunda kalması', ['Mahalledeki tarihi binaların cephelerinin orijinal mimariye uygun biçimde boyanarak koruma altına alınması', 'Kent dışındaki sanayi fabrikalarının çevre kirliliğini önlemek amacıyla organize sanayi bölgelerine taşınması', 'Üniversite öğrencilerinin yaz tatili döneminde memleketlerine gidip güz döneminde tekrar yurtlarına dönmesi'], 'Doğrudan veya dolaylı yerinden edilme, alt gelir gruplarının barınma hakkını ve sosyal dayanışma ağlarını kaybetmesine yol açan sınıfsal bir dışlanmadır.'),
  ('Tarihi veya köhneleşmiş bir mahallede konutlardan ziyade eski esnaf dükkanlarının yerini lüks restoranların, gurme marketlerin ve tasarım mağazalarının alması hangi alt kavramla ifade edilir?', 'Ticari soylulaştırma (butikleşme)', ['Kırsal soylulaştırma (eko-turizm)', 'Sanayi desantralizasyonu', 'Enformel gecekondulaşma'], 'Mahallenin perakende ve ticaret yapısının üst gelir grubunun tüketim alışkanlıklarına göre dönüşmesi ticari soylulaştırmadır.'),
  ('Kıyı kasabalarında veya doğası korunmuş köylerde kentli üst-orta sınıfların taş evleri satın alıp restore ederek yerleşmesi ve yerel köylü nüfusun arazi fiyatlarına erişemez hâle gelmesi ne olarak tanımlanır?', 'Kırsal soylulaştırma', ['Merkezi iş alanı çöküntüsü', 'Sanayi proletaryalaşması', 'Gecekondu apartmanlaşması'], 'Soylulaştırma yalnızca metropol merkezleriyle sınırlı kalmayıp kırsal ve kıyı yerleşimlerinde de sınıfsal el değiştirme (rural gentrification) yaratabilmektedir.'),
  ('Kapalı sitelerin 1980\'ler ve 1990\'lardan itibaren hem dünyada hem Türkiye\'de hızla yaygınlaşmasının ardındaki en güçlü sosyo-psikolojik ve sınıfsal motivasyonlardan biri nedir?', 'Suç korkusu, kentsel belirsizlikten kaçış ve kendilerine benzeyen homojen bir sınıfsal çevreyle bir arada yaşama arzusu', ['Farklı gelir ve etnik gruplarla aynı sokakta karşılaşarak toplumsal çeşitliliği deneyimleme isteği', 'Özel otomobil kullanımını tamamen bırakarak yalnızca belediye otobüsleriyle kent merkezine ulaşma hedefi', 'Mahalle muhtarlığı ve kamusal park yönetiminde alt gelir gruplarıyla ortak bütçe oluşturma çabası'], 'Teresa Caldeira ve Setha Low gibi araştırmacılar, kapalı sitelerin "suç korkusu söylemi" ve "prestij/statü ayrışması" üzerine inşa edildiğini ortaya koymuştur.'),
  ('Bir inşaat firmasının reklam kampanyasında "Şehrin karmaşasından uzak, seçkin komşularınızla 7/24 kameralı koruma altında kendi özel göletiniz ve kulübünüzle ayrıcalıklı bir dünya" sloganını kullanması neyi pazarlamaktadır?', 'Mekânsal ayrışmayı statü sembolü ve güvenlikli bir yaşam tarzı (kulüp malı) olarak', ['Herkesin eşit ve ücretsiz yararlanabildiği demokratik kamusal meydan kültürünü', 'Tarihi kent merkezindeki düşük gelirli kiracıları koruyan sosyal konut politikasını', 'Farklı toplumsal sınıfların aynı mahalle okulunda kaynaşmasını sağlayan entegrasyon modelini'], 'Kapalı site pazarlaması, kamusal kentten kopuşu "seçkinlik, homojen komşuluk ve steril güvenlik" vaadiyle metalaştırır.'),
  ('Ekonomi ve kent planlama literatüründe kapalı sitelerin sunduğu yüzme havuzu, özel park, güvenlik ve spor tesislerinin niteliği hangi kavramla tanımlanır?', 'Kulüp malları (aidat ödeyen üyelerin yararlanabildiği dışlayıcı ortak mallar)', ['Tam kamusal mallar (hiç kimsenin kullanımından dışlanamadığı ücretsiz mallar)', 'Enformel imece malları (akrabalık bağıyla kurulan kırsal ortaklıklar)', 'Devlet tekeli malları (yalnızca kamu memurlarının erişebildiği lojmanlar)'], 'Kapalı site donatıları ne tek kişilik özel maldır ne de herkese açık kamusal maldır; yalnızca mülk sahibi/kiracı üyelerin eriştiği "kulüp malı" (club goods) niteliğindedir.'),
  ('Jürgen Habermas\'ın "Kamusal Alanın Yapısal Dönüşümü" eserinde 18. yüzyıl Avrupa kentlerinde burjuva kamusal alanının filizlendiği mekânlar olarak öne çıkardığı yerler hangileridir?', 'Kahvehaneler (coffeehouses), edebiyat salonları ve kulüpler', ['Feodal derebeylik şatoları ve kapalı manastır hücreleri', 'Banliyö alışveriş merkezleri ve otoyol dinlenme tesisleri', 'Ağır sanayi fabrikaları ve gümrük depolama antrepoları'], 'Habermas, gazete ve dergilerin okunup siyasi-edebî meselelerin statü paranteze alınarak rasyonel biçimde tartışıldığı kahvehane ve salonları kamusal alanın çekirdeği sayar.'),
  ('1977\'de yayımlanan "Kamusal İnsanın Çöküşü" (The Fall of Public Man) adlı eserinde modern kentlerde kamusal yaşamın aşınmasını ve mahremiyet tiranlığını eleştiren sosyolog kimdir?', 'Richard Sennett', ['Ernest Burgess', 'Homer Hoyt', 'Ruth Glass'], 'Richard Sennett, yabancıların bir arada medeni biçimde etkileşime girdiği kamusal kültürün zayıflayıp narsisistik özel alan saplantısının yükselmesini eleştirmiştir.'),
  ('Jane Jacobs\'un kentsel sokak güvenliğini açıklamak için geliştirdiği ünlü "sokaktaki gözler" (eyes on the street) kavramı neyi ifade eder?', 'Farklı saatlerde açık esnafların, kaldırımdaki yayaların ve sokağa bakan pencerelerdeki sakinlerin doğal ve kendiliğinden bir toplumsal gözetim sağlayarak suçu önlemesini', ['Sokakların her köşesine yüz tanıma özellikli binlerce polis kamerası ve turnike sistemi yerleştirilmesini', 'Mahalle girişlerine bariyer konularak yabancı plakalı araçların ve yayaların kimlik kontrolüyle içeri alınmasını', 'Konutların sokakla bağlantısını kesmek için binaların etrafına üç metre yüksekliğinde sağır beton duvarlar örülmesini'], 'Jacobs\'a göre güvenli sokak ıssız ve duvarlı olan değil; dükkanlar, konutlar ve yayalar sayesinde gün boyu canlı kalan ve doğal gözetim üreten sokaktır.'),
  ('Alışveriş merkezlerinin (AVM) geleneksel kent meydanlarının ve çarşı sokaklarının yerini alması kent sosyolojisinde hangi kavramla eleştirilir?', 'Yarı-kamusal (sözde kamusal / özelleştirilmiş) tüketim mekânlarının yükselişi', ['Tam demokratik ve mülkiyetsiz halk meydanlarının genişlemesi', 'Kırsal takas pazarlarının metropol merkezlerini ele geçirmesi', 'Geçiş bölgesindeki sanayi atölyelerinin kooperatifleşmesi'], 'AVM\'ler kamusal bir sokak simülasyonu sunsa da özel mülkiyettir; girişte güvenlik elemesi yapılır, siyasal gösteri yapılamaz ve temel amaç tüketime yönlendirmektir.'),
  ('Marc Augé\'nin "Üstmodernliğin Antropolojisi" bağlamında kimliksiz, tarihsel bağlamdan ve kalıcı toplumsal ilişkiden yoksun havaalanları, otoyollar, zincir oteller ve süpermarketler için kullandığı kavram nedir?', 'Yok-yerler (non-places / yer olmayan yerler)', ['Hafıza mekânları (lieux de mémoire)', 'Üçüncü mekânlar (third places)', 'Eşmerkezli geçiş halkaları'], 'Marc Augé, antropolojik anlamda kimlik, ilişki ve tarih barındıran "yer"in karşısına geçicilik ve anonim sözleşmelerle işleyen "yok-yer"leri koyar.'),
  ('Ray Oldenburg\'un kentsel toplumsallaşma için hayati gördüğü; "ev (birinci mekân)" ve "işyeri (ikinci mekân)" dışında insanların gayriresmî biçimde sosyalleştiği mahalle kahvehaneleri, kütüphaneler ve parklar nasıl adlandırılır?', 'Üçüncü mekânlar (third places)', ['Yok-yerler (non-places)', 'Merkezi iş alanları (CBD)', 'Kulüp malları (club goods)'], 'Oldenburg\'a göre sivil yaşamı ve topluluk hissini besleyen erişilebilir, samimi ve statü farklarını yumuşatan buluşma noktaları "üçüncü mekân"lardır.'),
  ('Everett Lee\'nin kuramında kaynak ile hedef bölge arasındaki uzak mesafe, sıkı vize rejimleri, yüksek ulaşım maliyetleri ve sınır duvarları hangi kavramla karşılanır?', 'Araya giren engeller', ['Demografik fırsat penceresi', 'Ulusötesi sosyal ağlar', 'Kaynak bölgedeki nötr faktörler'], 'Göç niyetinin eyleme dönüşmesini zorlaştıran veya tamamen durduran fiziksel, ekonomik ve yasal kısıtlamalar araya giren engellerdir.'),
  ('Bir yazılımcı başka bir ülkeden yüksek maaşlı iş teklifi almasına rağmen bakmakla yükümlü olduğu yaşlı ebeveynlerini bırakamaması nedeniyle göç etmekten vazgeçmiştir. Everett Lee modeline göre bu durum hangisine örnektir?', 'Kişisel faktörler', ['Kaynak bölgenin çekici kurumsal yapısı', 'Hedef ülkenin kota ve vize engelleri', 'Coğrafi mesafenin yarattığı ulaşım maliyeti'], 'Bireyin aile bağları, yaşam döngüsü evresi, algısı ve karakter özellikleri Lee kuramında göç kararını şekillendiren kişisel faktörlerdir.'),
  ('Everett Lee\'ye göre aynı köyde yaşayan iki kişiden birinin kuraklığı göç nedeni sayarken diğerinin toprağına bağlı kalarak köyde kalmayı sürdürmesi kuramın hangi temel varsayımını doğrular?', 'İtici ve çekici faktörlerin nesnel varlığından ziyade bireyler tarafından nasıl algılandığının belirleyici olmasını', ['Göç hareketlerinin yalnızca devletlerin zorlayıcı yasal düzenlemeleriyle başlayabileceğini', 'Kırsal bölgelerde hiçbir zaman nötr veya çekici unsurların bulunamayacağını', 'Araya giren engellerin bütün toplumsal sınıflar için tamamen eşit düzeyde işlediğini'], 'Lee\'ye göre göç kararı salt nesnel koşulların mekanik bir sonucu değil, bu koşulların bireysel algı süzgecinden geçirilmesiyle oluşan bir değerlendirmedir.'),
  ('Everett Lee\'nin "Bir Göç Kuramı" (A Theory of Migration) adlı kurucu çalışması hangi yılda bilim dünyasına sunulmuştur?', '1966', ['1798', '1929', '1991'], 'Everett S. Lee, modern göç çalışmalarının temel taşlarından biri olan makalesini 1966 yılında Demography dergisinde yayımlamıştır.'),
  ('Everett Lee\'nin göç şemasında hem kaynak bölgede hem de hedef bölgede bulunan ve bireylerin göç kararını olumlu ya da olumsuz yönde etkilemeyen unsurlar hangi işaretle gösterilir?', 'Sıfır (0) işaretiyle', ['Çift yönlü ok (↔) işaretiyle', 'Sonsuzluk (∞) sembolüyle', 'Ünlem (!) işaretiyle'], 'Lee\'nin diyagramında çekici unsurlar artı (+), itici unsurlar eksi (-), bireyleri ilgilendirmeyen nötr unsurlar ise sıfır (0) ile simgelenir.'),
  ('Everett Lee\'nin göç hacmine ilişkin hipotezlerine göre kaynak bölge ile hedef bölge arasındaki ekonomik ve toplumsal çeşitlilik arttıkça göç hacminde nasıl bir değişim beklenir?', 'Araya giren engeller sabit kaldığı sürece göç hacmi artış gösterir', ['Bölgeler arası farklılıklar göç isteğini tamamen ortadan kaldırır', 'Yalnızca tersine göç akımlarında tek yönlü bir yükseliş yaşanır', 'Göç edenlerin eğitim düzeyi düştükçe mesafe etkisi tamamen sıfırlanır'], 'Bölgeler arasındaki gelişmişlik, uzmanlaşma ve fırsat farklılıklarının büyümesi Lee\'ye göre göç akımlarının hacmini artıran temel dinamiklerden biridir.'),
  ('1951 Cenevre Sözleşmesi\'nde yer alan "1 Ocak 1951 öncesi olaylar" ve "Avrupa ile sınırlılık" kısıtlamalarını uluslararası ölçekte kaldıran ek protokol hangi yılda yürürlüğe girmiştir?', '1967', ['1955', '1982', '2001'], '1967 tarihli New York Protokolü, Cenevre Sözleşmesi\'ndeki zaman ve coğrafya sınırlamalarını kaldırarak mülteci tanımına evrensel bir nitelik kazandırmıştır.'),
  ('Uluslararası koruma ve mülteci statüsü almak üzere başka bir ülkeye başvuruda bulunmuş, ancak yetkili makamlarca statü belirleme süreci henüz sonuçlandırılmamış kişiye ne ad verilir?', 'Sığınmacı', ['Ekonomik göçmen', 'Diplomatik temsilci', 'Vatansız kişi'], 'Sığınmacı (asylum seeker), mülteci olduğunu iddia ederek koruma talep eden fakat hukuki incelemesi henüz kesinleşmemiş kişiyi ifade eder.'),
  ('Uluslararası hukuk açısından "göçmen" (ekonomik göçmen) ile "mülteci" kavramları arasındaki en temel yapısal fark aşağıdakilerden hangisidir?', 'Göçmenin vatandaşı olduğu devletin korumasından yararlanmayı sürdürebilmesi, mültecinin ise zulüm riski nedeniyle kendi devletinin korumasından yoksun kalması', ['Mültecilerin yalnızca komşu ülkelere gidebilmesi, ekonomik göçmenlerin ise sadece kıtalar arası yolculuk yapabilmesi', 'Ekonomik göçmenlerin gittikleri ülkede hiçbir vergi ödememesi, mültecilerin ise çifte vergilendirmeye tabi tutulması', 'Mülteci statüsünün en fazla altı ay geçerli olması, ekonomik göçmenliğin ise doğuştan kazanılan kalıcı bir statü olması'], 'Ekonomik göçmen istediğinde kendi ülkesine güvenle dönebilir ve konsolosluk korumasından faydalanabilir; mülteci ise zulüm tehlikesi nedeniyle bu korumadan yararlanamaz.'),
  ('Uluslararası mülteci hukukunun temel taşı sayılan ve bir kişinin hayatının ya da özgürlüğünün tehdit altında olacağı bir ülkeye zorla gönderilmesini yasaklayan ilke hangisidir?', 'Geri göndermeme ilkesi', ['Karşılıklı vize muafiyeti ilkesi', 'Diplomatik dokunulmazlık kuralı', 'Toprak esasına göre vatandaşlık ilkesi'], '1951 Sözleşmesi\'nin 33. maddesinde düzenlenen geri göndermeme (non-refoulement) ilkesi, sığınmacı ve mültecilerin zulüm görecekleri yerlere iadesini kesin olarak yasaklar.'),
  ('Savaş, iç çatışma, insan hakları ihlalleri veya afetler nedeniyle evlerini terk etmek zorunda kalmalarına rağmen uluslararası bir sınırı geçmeyerek kendi ülkeleri içinde kalan kişilere ne ad verilir?', 'Ülke içinde yerinden edilmiş kişiler', ['Ulusötesi şartlı mülteciler', 'Kıtalar arası transit sığınmacılar', 'Hukuki anlamda vatansız bireyler'], 'Mültecilerle benzer zorlayıcı nedenlerle yer değiştiren ancak uluslararası sınır aşmadıkları için 1951 Sözleşmesi kapsamına girmeyen gruplar ülke içinde yerinden edilmiş kişilerdir (IDP).'),
  ('Bir ülkeye yasal giriş yollarını kullanmadan, geçerli vize ve pasaport olmaksızın giren ya da yasal kalış süresi dolduğu halde ülkeden ayrılmayan kişilerin durumu göç literatüründe hangi teknik kavramla tanımlanır?', 'Düzensiz göç', ['Beyin göçü', 'Zorunlu mübadele', 'Nitelikli sirküler göç'], 'Uluslararası göç hukukunda "yasadışı göçmen" ifadesi yerine insan onurunu koruyan ve idari/hukuki prosedür eksikliğine vurgu yapan "düzensiz göç" terimi tercih edilir.'),
  ('Hiçbir devlet tarafından kendi ulusal mevzuatı işleyişi çerçevesinde vatandaş olarak kabul edilmeyen ve uyrukluk bağı bulunmayan kişiye uluslararası hukukta ne ad verilir?', 'Vatansız', ['Transit sığınmacı', 'Çifte uyruklu göçmen', 'Mevsimlik tarım işçisi'], '1954 tarihli Sözleşme uyarınca hiçbir devletin kendi hukukuna göre vatandaş saymadığı kişiye vatansız (apatrid / haymatlos) denir.'),
  ('1951 yılında kurulan ve 2016\'da Birleşmiş Milletler ile kurumsal bağ kurarak küresel göç yönetimi alanında lider kuruluş konumuna gelen örgüt hangisidir?', 'Uluslararası Göç Örgütü (IOM)', ['Dünya Ticaret Örgütü (WTO)', 'Uluslararası Para Fonu (IMF)', 'Kuzey Atlantik Antlaşması Örgütü (NATO)'], 'Uluslararası Göç Örgütü (IOM), insani ve düzenli göçün hem göçmenlerin hem de toplumların yararına yönetilmesi için çalışan temel küresel kuruluştur.'),
  ('Ernst Georg Ravenstein\'ın 19. yüzyılın sonlarında ortaya koyduğu "Göç Kanunları"na göre kırsal kesimden büyük metropollere yönelen göçlerin işleyiş biçimi nasıldır?', 'Köyden önce yakın kasaba ve küçük şehirlere, oradan büyük metropollere doğru basamaklı (kademeli) olarak gerçekleşir', ['Her zaman en uzak kıtadaki en büyük sanayi şehrine tek seferde ve kesintisiz biçimde yapılır', 'Göç hareketlerine yalnızca altmış beş yaş üstü emekli nüfus katılırken genç nüfus kırsalda kalır', 'Uzun mesafeli ticaret merkezlerine yönelen göçlerde kadınların oranı erkeklerden her koşulda daha yüksektir'], 'Ravenstein (1885), göçlerin çoğunlukla kısa mesafeli olduğunu ve büyük merkezlere doğru basamaklı (step migration) bir sıra izlediğini belirlemiştir.'),
  ('Ravenstein\'ın göç yasalarından biri olan "kısa mesafeli göçlerde kadınlar, uluslararası ve uzun mesafeli göçlerde ise tarihsel olarak erkekler daha ağırlıklıdır" tespiti, yirminci yüzyılın son çeyreğinden itibaren hangi yeni sosyolojik kavramla yeniden tartışmaya açılmıştır?', 'Göçün kadınlaşması', ['Demografik yaşlanma tuzağı', 'Malthusçu pozitif nüfus kontrolü', 'Kırsal feodal kapalı ekonomi'], 'Küresel bakım emeği, hizmet sektörü ve eğitim olanaklarının genişlemesiyle birlikte bağımsız hareket eden kadın göçmen oranının hızla artması literatürde "göçün kadınlaşması" olarak adlandırılır.'),
  ('Bir fındık üreticisinin ağustos ayında ailesiyle birlikte Şanlıurfa\'dan Ordu\'ya gidip bahçelerde çalıştıktan sonra eylül sonunda Şanlıurfa\'daki ikametgâhına geri dönmesi sürecinde Ordu ilinin nüfus dinamiklerinde hangi durum gözlenir?', 'Hasat döneminde geçici (fiili) nüfus artarken adrese dayalı kalıcı nüfus sabit kalır', ['Ordu ilinin aritmetik nüfus yoğunluğu yılın on iki ayı boyunca kalıcı biçimde ikiye katlanır', 'Şanlıurfa ve Ordu illeri arasında uluslararası dış göç istatistikleri güncellenir', 'Türkiye\'nin toplam nüfus miktarında hasat süresince mevsimlik bir artış meydana gelir'], 'Mevsimlik tarım göçü iç ve geçici bir hareket olduğu için gidilen ilde yalnızca o mevsimdeki fiili nüfusu artırır, ülke toplam nüfusunu ise değiştirmez.'),
  ('Asya\'daki bir ülkeden yola çıkan göçmen grubunun nihai hedefi Batı Avrupa ülkelerine yerleşmek olmasına rağmen, geçiş güzergâhındaki bir Akdeniz ülkesinde sınır kontrollerinin sıkılaşması nedeniyle yıllarca kalmak zorunda kalması transit göçün hangi özelliğini gösterir?', 'Transit göçün engeller nedeniyle zamanla kalıcı göçe dönüşebilme potansiyelini', ['Transit göçmenlerin yola çıkmadan önce her zaman hedef ülkeden vatandaşlık aldığını', 'Geçiş ülkelerinin göç süreçlerinden ekonomik ve sosyal açıdan hiç etkilenmediğini', 'Mevsimlik turizm hareketlerinin zorunlu nüfus mübadelesiyle birebir aynı olduğunu'], 'Araya giren hukuki ve fiziki engeller aşılamadığında, başlangıçta geçici bir köprü olarak görülen transit ülkeler fiili hedef ülkeye dönüşebilir.'),
  ('Göçmenlerin kaynak ülke ile hedef ülke arasında düzenli aralıklarla gidip gelerek her iki ekonomide de dönemsel çalışma ve yaşam pratiği sürdürmesi hangi kavramla açıklanır?', 'Döngüsel (sirküler) göç', ['Tek yönlü kalıcı iskan', 'Zorunlu siyasi sürgün', 'Kitlesel mülteci akını'], 'Tek yönlü ve kopuşa dayalı kalıcı göçten farklı olarak, göçmenin menşe ve varış ülkeleri arasında tekrarlayan hareketlilik göstermesi döngüsel (sirküler) göçtür.'),
  ('Daha önce hedef ülkeye yerleşmiş akraba, hemşehri ve tanıdıkların yeni gelecek göçmenlere barınma, iş bulma ve uyum konularında destek sağlayarak göç maliyetlerini ve risklerini düşürmesi hangi kavramla ifade edilir?', 'Göçmen ağları', ['Araya giren yasal engeller', 'Demografik yaşlanma krizi', 'Coğrafi çekince uygulaması'], 'Göçmen ağları (network kuramı), öncü göçmenlerle geride kalanlar arasındaki kişilerarası bağların göçü kendi kendini besleyen (kümülatif) bir sürece dönüştürdüğünü açıklar.'),
  ('Anadolu\'daki belirli bir ilçeden çıkan ilk birkaç işçinin Avrupa\'daki belirli bir sanayi kasabasına yerleşmesinin ardından, yirmi yıl içinde aynı ilçenin nüfusunun yarısının tam olarak aynı kasabaya göç etmiş olması hangi olgunun tipik bir örneğidir?', 'Zincirleme göç', ['Zorunlu nüfus mübadelesi', 'İklim mülteciliği', 'Kentten kıra mevsimlik göç'], 'Öncü göçmenlerin kurduğu hemşehrilik ve akrabalık bağları üzerinden aynı yerleşim yerinden aynı hedef noktaya birbirini izleyerek gerçekleşen göçlere zincirleme göç denir.'),
  ('Yurt dışına göç etmiş bilim insanları, mühendisler ve girişimcilerin ana vatanlarına kesin dönüş yapmaları ya da bilgi, teknoloji ve sermaye ağlarını ülkelerine aktarmaları literatürde hangi olumlu kavramla karşılanır?', 'Beyin kazanımı', ['Düzensiz transit sığınma', 'Kırsal işgücü kaybı', 'Zorunlu iskan politikası'], 'Nitelikli işgücünün ülkesine geri dönmesi veya diasporadaki uzmanlığın menşe ülkeye aktarılması "beyin kazanımı" (brain gain) ya da tersine beyin göçü olarak adlandırılır.'),
  ('Kuraklık, çölleşme, deniz seviyesinin yükselmesi ve aşırı hava olayları nedeniyle yaşam alanları kullanılamaz hale gelen insanların göç etmek zorunda kalması literatürde hangi kavramla tartışılmaktadır?', 'İklim göçü', ['Serbest dolaşımlı turizm göçü', 'Nitelikli beyin kazanımı', 'Mevsimlik yayla dinlenmesi'], 'Çevresel bozulma ve iklim krizi kaynaklı zorunlu yer değiştirmeler iklim göçü veya çevresel göç olarak adlandırılır.'),
  ('Bir kentin bir yıllık süre içinde aldığı göç 45.000, verdiği göç 60.000, aynı yıldaki doğum sayısı 30.000 ve ölüm sayısı 10.000 olarak kaydedilmiştir. Bu kentin net göç miktarı ve gerçek nüfus değişimi aşağıdakilerden hangisidir?', 'Net göç -15.000, gerçek nüfus değişimi ise +5.000 kişidir', ['Net göç +15.000, gerçek nüfus değişimi ise +35.000 kişidir', 'Net göç -105.000, gerçek nüfus değişimi ise -20.000 kişidir', 'Net göç +20.000, gerçek nüfus değişimi ise -15.000 kişidir'], 'Net göç = 45.000 - 60.000 = -15.000\'dir. Doğal artış = 30.000 - 10.000 = +20.000\'dir. Gerçek nüfus artışı = Doğal artış + Net göç = 20.000 + (-15.000) = +5.000 kişidir.'),
  ('Yıl ortası nüfusu 500.000 olan bir il bir yıl içinde 18.000 göç almış ve 8.000 göç vermiştir. Demografik hesaplama yöntemine göre bu ilin net göç hızı binde kaçtır?', 'Binde +20', ['Binde +52', 'Binde -10', 'Binde +100'], 'Net göç = 18.000 - 8.000 = +10.000\'dir. Net göç hızı (yaklaşık yıl ortası nüfusa oranla) = (10.000 / 500.000) × 1000 = binde +20 olarak hesaplanır.'),
  ('Kırsaldan kente yönelik göçleri azaltmak ve ülke içinde dengeli bir nüfus dağılımı sağlamak isteyen bir devletin uygulayacağı aşağıdaki politikalardan hangisi doğrudan kaynak bölgedeki itici faktörleri zayıflatmaya yöneliktir?', 'Kırsalda sulamalı modern tarımı, tarıma dayalı sanayiyi, eğitim ve sağlık altyapısını güçlendirmek', ['Büyükşehirlere girişlerde iç pasaport ve vize uygulaması başlatarak seyahat özgürlüğünü kaldırmak', 'Kent merkezlerindeki gecekonduları hiçbir alternatif konut üretmeden yıkarak insanları sokağa bırakmak', 'Yalnızca metropol ilçelere yeni organize sanayi bölgeleri ve üniversite kampüsleri açmak'], 'Kırsal kalkınma hamleleriyle yerinde istihdam ve kaliteli kamu hizmeti sunmak, insanları göçe zorlayan itici faktörleri kaynağında azaltan yapısal bir çözümdür.'),
  ('Çalışmak amacıyla yabancı ülkelere giden göçmenlerin kazandıkları paranın bir bölümünü menşe ülkelerindeki ailelerine göndermelerine ekonomi ve göç literatüründe ne ad verilir?', 'İşçi dövizleri', ['Doğrudan yabancı sermaye kamulaştırması', 'Gümrük birliği telafi fonu', 'Uluslararası mülteci tazminatı'], 'Göçmenlerin ana vatanlarındaki yakınlarına gönderdikleri tasarruflara işçi dövizleri (remittances) denir ve gelişmekte olan ülkelerin ödemeler dengesi için önemli bir döviz girdisidir.'),
  ('Tarihteki Kavimler Göçü ile Yeni Çağ\'da Avrupalıların keşfedilen Amerika ve Okyanusya kıtalarına yerleşmesi karşılaştırıldığında her iki göç dalgasının ortak özelliği hangisidir?', 'Uzun vadede kıtaların etnik, kültürel ve demografik haritasını kalıcı biçimde değiştiren büyük ölçekli dış göçler olmaları', ['Yalnızca yaz aylarında turizm amacıyla yapılıp kış mevsiminde başlangıç noktasına dönülen geçici hareketler olmaları', '1951 Cenevre Sözleşmesi hükümlerine göre Birleşmiş Milletler gözetiminde yürütülmüş olmaları', 'Hiçbir siyasi çatışma, ekonomik arayış veya nüfus baskısı içermeyen bireysel öğrenci değişimleri olmaları'], 'Hem Kavimler Göçü hem de Yeni Dünya göçleri kitlesel ve kalıcı sonuçlar doğurarak dünya siyasi ve demografik yapısını kökten dönüştürmüştür.'),
  ('İkinci Dünya Savaşı sonrasında Batı Avrupa ülkelerinin yıkılan ekonomilerini yeniden inşa etmek ve sanayideki işgücü açığını kapatmak için Türkiye, İtalya ve İspanya gibi ülkelerden kabul ettiği işçileri tanımlamak üzere Almanya\'da kullanılan kavram hangisidir?', 'Misafir işçi', ['Şartlı mülteci', 'Zorunlu mübadil', 'Vatansız sığınmacı'], 'Başlangıçta belirli bir süre çalışıp ülkelerine dönecekleri varsayımıyla ikili işgücü antlaşmaları kapsamında kabul edilen işçilere "Gastarbeiter" (misafir işçi) denilmiştir.'),
  ('Bir göçmenin vardığı ülkede kendi dilini, kültürünü ve kimliğini tamamen terk ederek egemen toplumun kültürel kalıpları içinde erimesini bekleyen uyum politikası modeli hangisidir?', 'Asimilasyon', ['Çokkültürlülük', 'Ulusötesilik', 'Kültürel çoğulculuk'], 'Asimilasyoncu model, göçmenlerin köken kültürlerini kamusal ve zamanla özel alandan silerek ev sahibi toplumun homojen kimliğine tek taraflı benzemesini öngörür.'),
  ('Ev sahibi toplum ile göçmen grupların karşılıklı etkileşim içinde ortak yasal ve toplumsal yaşama katılırken göçmenlerin kendi kültürel kimliklerini de koruyabildiği uyum süreci nasıl adlandırılır?', 'Entegrasyon', ['Zorunlu asimilasyon', 'Mekânsal gettolaşma', 'Sınır dışı etme'], 'Entegrasyon, asimilasyondan farklı olarak tek taraflı kimlik silinmesini değil; göçmen ile yerel toplum arasında karşılıklı uyumu ve eşit haklarla toplumsal yaşama katılımı savunur.'),
  ('Göçmenlerin kent merkezlerinde ev sahibi toplumdan yalıtılmış, sosyoekonomik açıdan dezavantajlı ve kendi içine kapalı belirli mahallelerde yoğunlaşması hangi kavramla ifade edilir?', 'Mekânsal ayrışma', ['Tersine beyin kazanımı', 'Demografik geçiş dengesi', 'Sirküler turizm göçü'], 'Ekonomik eşitsizlik, ayrımcılık ve barınma engelleri nedeniyle göçmen grupların kentin çeperlerinde veya çöküntü alanlarında izole biçimde toplanmasına mekânsal ayrışma/gettolaşma denir.'),
  ('Ekonomik daralma dönemlerinde ev sahibi ülkedeki işsizliğin ve kamu hizmetlerindeki aksamaların tek sorumlusu olarak göçmenlerin gösterilmesi sosyal psikolojide hangi mekanizmayla açıklanır?', 'Günah keçisi ilan etme', ['Pozitif göç seçiciliği', 'Karşılıklı kültürlenme', 'Demografik fırsat penceresi'], 'Yapısal ekonomik ve politik krizlerin yarattığı toplumsal öfkenin savunmasız azınlık veya göçmen gruplara yöneltilmesine "günah keçisi ilan etme" denir.'),
  ('Üniversite eğitimi için dört yıllığına başka bir ildeki fakülteye kayıt yaptıran, yurtlarda kalan ve mezuniyetin ardından farklı bir sanayi kentinde işe başlayan bir gencin hareketliliği göç sınıflandırmasında nasıl değerlendirilir?', 'Eğitim ve istihdam odaklı gönüllü iç göç süreçleri', ['1951 Cenevre Sözleşmesi kapsamında şartlı mültecilik', 'Uluslararası zorunlu nüfus mübadelesi uygulaması', 'Sınır ötesi düzensiz transit göç hareketliliği'], 'Kişinin ülke sınırları içinde eğitim ve ardından kariyer amacıyla kendi isteğiyle yer değiştirmesi gönüllü iç göç örnekleridir.'),
  ('Büyük baraj projeleri (örneğin Keban veya Ilısu Barajı) sonucunda yerleşim yerleri ve tarım alanları baraj gölü suları altında kalan köylülerin başka bölgelere yerleştirilmesi hangi göç kategorisine girer?', 'Kalkınma kaynaklı zorunlu iç göç', ['Gönüllü uluslararası beyin göçü', 'Mevsimlik yaylacılık hareketi', 'Sınır ötesi siyasi iltica'], 'Baraj, maden veya büyük altyapı yatırımları nedeniyle yaşam alanlarının kamulaştırılarak boşaltılması literatürde kalkınma kaynaklı yerinden edilme (zorunlu iç göç) olarak sınıflandırılır.'),
  ('Göç istatistiklerinde insanların yalnızca doğdukları yer ile sayım anında yaşadıkları yer karşılaştırılarak elde edilen "yaşam boyu göç" verisinin temel metodolojik sınırlılığı nedir?', 'Doğum ile sayım tarihi arasında yapılan ara göçleri ve doğduğu yere geri dönüşleri gizlemesi', ['Ülkedeki toplam kadın ve erkek nüfus oranını hesaplamayı tamamen engellemesi', 'Yalnızca bir haftalık turistik otel konaklamalarını kalıcı göç olarak kaydetmesi', 'Sadece doksan yaşın üzerindeki bireylerin nüfus kayıtlarını dikkate alması'], 'Yaşam boyu göç ölçümü sadece başlangıç (doğum yeri) ve son noktayı (mevcut ikamet) kıyasladığından aradaki çoklu göçleri ve geri dönüş hareketlerini yakalayamaz.'),
  ('Sanayileşmiş bir kent merkezinde yaşayan fabrika işçisinin her sabah komşu ilçedeki evinden trenle fabrikaya gidip akşam evine dönmesi göç bilimi açısından nasıl sınıflandırılır?', 'İkametgâh değişikliği içermediği için göç sayılmayan günlük gidip gelme (komütasyon) hareketidir', ['İlçe sınırları aşıldığı için kalıcı iç göç istatistiklerine her gün yeniden eklenir', 'Uluslararası çalışma örgütü kurallarına göre mevsimlik tarım göçü kapsamındadır', 'Zorunlu yerinden edilme statüsünde değerlendirilen kitlesel bir sığınma hareketidir'], 'Göçten söz edebilmek için olağan ikametgâhın kalıcı veya belirli bir süreliğine değiştirilmesi gerekir; ev ile iş arasındaki günlük hareketlilik (commuting) göç değildir.'),
  ('Göç alan bir ülkede yerli nüfusun yaş ortalamasının yüksek, gelen göçmen nüfusun ise genç çalışma çağında yoğunlaşmış olması ev sahibi ülkenin sosyal güvenlik sistemi üzerinde kısa ve orta vadede nasıl bir etki yaratabilir?', 'Kayıtlı istihdama katıldıkları takdirde aktif çalışan/emekli dengesini destekleyerek emeklilik fonlarının finansmanına olumlu katkı sunar', ['Çalışma çağındaki genç göçmenlerin tamamı ilk günden yaşlılık aylığı alacağı için emeklilik sistemini anında çökertir', 'Ülkedeki doğum oranlarını negatif sayıya düşürerek ilkokul ihtiyacını tamamen ortadan kaldırır', 'Yaşlı yerli nüfusun biyolojik yaşını küçülterek ortanca yaşı bir gecede sıfıra indirir'], 'Demografik yaşlanma yaşayan ülkelerde genç göçmenlerin kayıtlı işgücüne katılımı, vergi ve prim gelirlerini artırarak yaşlı bağımlılık yükünü hafifletebilir.'),
  ('Durkheim\'a göre mekanik dayanışmanın hâkim olduğu toplumlarda hukuk sistemi ağırlıklı olarak hangi özelliğe sahiptir?', 'Cezalandırıcı (bastırıcı) hukuk', ['Onarıcı (iade edici) hukuk', 'Ticari tahkim ve uzlaşı hukuku', 'İdari ve sözleşmesel düzenleme hukuku'], 'Kolektif bilincin güçlü olduğu mekanik dayanışmalı toplumlarda suça karşı sert ve bastırıcı ceza hukuku ön plandadır.'),
  ('Organik dayanışmanın egemen olduğu karmaşık işbölümlü toplumlarda Durkheim hangi hukuk türünün ağırlık kazandığını belirtir?', 'Onarıcı (iade edici) hukuk', ['Bastırıcı ve bedensel ceza hukuku', 'Örfi ve dinsel kefaret hukuku', 'Kan davasına dayalı misilleme hukuku'], 'Organik dayanışmada amaç bozulan karşılıklı ilişkileri eski haline getirmek olduğundan medeni, ticari ve idari nitelikli onarıcı hukuk baskındır.'),
  ('Bir köyde herkesin benzer tarımsal işleri yapması ve ortak inançları sorgusuz paylaşması Durkheim\'ın hangi kavram çiftiyle en doğru açıklanır?', 'Güçlü kolektif bilinç ve mekanik dayanışma', ['Zayıf kolektif bilinç ve organik dayanışma', 'Anomik işbölümü ve bürokratik rasyonelleşme', 'Esnek uzmanlaşma ve sözleşmesel bireycilik'], 'Benzer işler ve güçlü ortak inançlar mekanik dayanışma ile yüksek kolektif bilincin temel göstergeleridir.'),
  ('Bir hastanede cerrah, anestezi uzmanı, hemşire ve laboratuvar teknisyeninin farklı görevler üstlenerek birbirine muhtaç biçimde çalışması hangi sosyolojik kavrama örnektir?', 'Organik dayanışma', ['Mekanik dayanışma', 'Yabancılaşmış cemaat yapısı', 'Karizmatik iş örgütlenmesi'], 'Farklılaşmış ve uzmanlaşmış rollerin karşılıklı bağımlılık içinde bütünleşmesi organik dayanışmanın somut örneğidir.'),
  ('Mekanik dayanışmadan organik dayanışmaya geçiş sürecinde bireyselliğin konumu hakkında Durkheim ne ileri sürer?', 'Kolektif bilincin daralmasıyla bireysel kişilik ve özerklik alanı genişler', ['Bireysellik tamamen ortadan kalkarak tek tip cemaat kimliğine dönüşür', 'Bireyler uzmanlaştıkça topluma olan karşılıklı bağımlılıkları tamamen sona erer', 'Bireysel haklar yalnızca geleneksel klan reislerinin izniyle kullanılabilir hale gelir'], 'İşbölümü ilerledikçe kolektif bilinç daha soyut hale gelir ve bireysel farklılık ile özerklik alanı genişler.'),
  ('Durkheim\'ın işbölümünün bir başka anormal biçimi olarak tanımladığı, örgüt içinde görevlerin kötü dağıtılması sonucu iş akışının süreksiz ve verimsiz kalması durumu nedir?', 'Eşgüdümsüz (bürokratik/koordinasyonsuz) işbölümü', ['Geleneksel mekanik bütünleşme', 'Karizmatik liderlik krizi', 'Duygusal emek tükenmişliği'], 'Görevlerin yeterli sürekli iş ve koordinasyon sağlayamayacak biçimde bölünmesi Durkheim\'ın üçüncü anormal işbölümü biçimidir.'),
  ('Taylorist yönetim anlayışının temel ilkelerinden biri olan "tasarım ile uygulamanın birbirinden ayrılması" ne anlama gelir?', 'İşin nasıl yapılacağının planlanmasının yönetime, yalnızca fiziksel icrasının ise işçiye bırakılması', ['İşçilerin kendi çalışma saatlerini ve üretim yöntemlerini bağımsız olarak tasarlaması', 'Fabrika binalarının mimari tasarımı ile makine bakımının aynı ustabaşı tarafından yürütülmesi', 'Üretim sürecindeki tüm zihinsel kararların sendika temsilcilerine devredilmesi'], 'Taylorizm\'de zihinsel planlama mühendis ve yöneticilerde toplanır; işçiden yalnızca talimatları harfiyen uygulaması beklenir.'),
  ('Taylor\'ın "parça başı farklılaştırılmış ücret sistemi" (differential piece-rate system) işçiyi öncelikle hangi varsayımla motive etmeyi hedefler?', 'İşçinin rasyonel ekonomik çıkar peşinde koşan "homo economicus" olduğu varsayımıyla', ['İşçinin yalnızca iş arkadaşlarıyla kurduğu samimi sosyal bağlardan güç aldığı varsayımıyla', 'Çalışanların maddi ödülden bağımsız olarak sanatsal yaratıcılık aradığı varsayımıyla', 'Ücret artışının işçileri tembelliğe sevk edeceği yönündeki geleneksel merkantilist varsayımla'], 'Taylorizm insanı ağırlıklı olarak maddi kazançla güdülenen ekonomik varlık olarak görür ve standart üstü üretime yüksek parça başı prim verir.'),
  ('Bir çağrı merkezinde çalışanların müşteriye söyleyeceği her cümlenin saniyesi saniyesine senaryolaştırılması ve konuşma sürelerinin yazılımla denetlenmesi hangi klasik yaklaşımın güncel yansımasıdır?', 'Dijital Taylorizm', ['Post-Fordist zanaat özerkliği', 'Mekanik cemaat dayanışması', 'Patrimonyal lonca yönetimi'], 'Hizmet sektöründe görevlerin en ince ayrıntısına kadar standartlaştırılıp süreyle ölçülmesi Neo-Taylorizm veya dijital Taylorizm olarak adlandırılır.'),
  ('Taylor ile birlikte hareket etütlerini fotoğraf ve film teknikleriyle geliştirerek temel el hareketlerini "therblig" birimleriyle sınıflandıran araştırmacı çift kimdir?', 'Frank ve Lillian Gilbreth', ['Sidney ve Beatrice Webb', 'Robert ve Helen Lynd', 'ferdinand Tönnies ve Georg Simmel'], 'Frank ve Lillian Gilbreth çifti hareket etüdünü geliştirmiş ve soyadlarının tersten yazılışından esinlenen "therblig" kavramını üretmiştir.'),
  ('Henry Ford\'un 1914 yılında işçilere dönemin piyasa ortalamasının üzerinde olan "günlük 5 dolar ücret" ve 8 saatlik işgünü uygulamasını getirmesinin sosyoekonomik gerekçesi nedir?', 'Yüksek işgücü devrini (işten ayrılmaları) azaltmak ve işçileri kitlesel üretimin tüketicisi haline getirmek', ['Fabrikadaki sendikaların yönetime ortak olma talebini kalıcı bir yasayla resmileştirmek', 'Montaj hattını tamamen kaldırıp yeniden geleneksel zanaat üretimine geçişi finanse etmek', 'Devletin koyduğu zorunlu asgari ücret yasasına uymadığı için kesilen vergi cezalarını kapatmak'], 'Ağır ve tekdüze bant çalışması yüzünden çok yükselen işçi devrini düşürmek ve kitle tüketimini desteklemek "5 dolarlık işgünü" kararının temel nedenleridir.'),
  ('Fordizm ile Taylorizm arasındaki ilişki çalışma sosyolojisinde en doğru biçimde nasıl açıklanır?', 'Fordizm, Taylorist iş bölümü ilkelerini hareketli montaj hattı teknolojisi ve kitle tüketimiyle birleştirmiştir', ['Fordizm, Taylor\'ın işbölümü ve standartlaştırma ilkelerini tamamen reddederek zanaatkârlığı savunmuştur', 'Taylorizm yalnızca tarım sektöründe, Fordizm ise yalnızca bankacılık ve finans sektöründe uygulanmıştır', 'Taylorizm kitle tüketimini ve refah devletini merkeze alırken Fordizm yalnızca el aletleriyle üretimi savunmuştur'], 'Fordizm, Taylorizm\'in parçalanmış görev yapısını mekanik kayan bantla bütünleştirip yüksek ücret-kitle tüketimi rejimiyle tamamlamıştır.'),
  ('Fordist bir otomobil fabrikasında kullanılan makinelerin ve işgücünün niteliği aşağıdakilerden hangisiyle karakterize edilir?', 'Tek amaçlı özel makineler ve yarı vasıflı/vasıfsız montaj işçileri', ['Çok amaçlı programlanabilir makineler ve çok vasıflı özerk zanaatkârlar', 'Geleneksel el tezgâhları ve lonca ustalarından oluşan bağımsız üreticiler', 'Tamamen evden çalışan serbest zamanlı yazılım ve tasarım uzmanları'], 'Fordizm\'de tek bir işlemi yüksek hızda yapan özel amaçlı sabit makineler ile kolayca ikame edilebilen yarı vasıflı bant işçileri kullanılır.'),
  ('Bir konserve fabrikasında işçilerin yerinden hiç ayrılmadan önlerinden sabit hızla geçen kutulara gün boyu yalnızca kapak yerleştirme işlemi yapması hangi üretim organizasyonuna örnektir?', 'Fordist kayan bant üretimi', ['Post-Fordist kalite çemberi', 'Yalın üretimde iş rotasyonu', 'Zanaat tipi sipariş üretimi'], 'Ürünün hareketli bant üzerinde aktığı ve sabit işçinin tek bir tekrarlı işlemi yaptığı düzen Fordist montaj hattının tipik örneğidir.'),
  ('Japon otomotiv firması Toyota\'da Taiichi Ohno öncülüğünde geliştirilen, stoksuz ve israfsız üretimi hedefleyen Post-Fordist üretim yaklaşımı hangisidir?', 'Toyotizm (Yalın üretim)', ['Bilimsel yönetim (Taylorizm)', 'Bürokratik patrimonyalizm', 'Fizyokratik üretim modeli'], 'Stokları ve her türlü israfı (muda) sıfırlamayı amaçlayan Toyota Üretim Sistemi literatürde Toyotizm veya yalın üretim olarak bilinir.'),
  ('Fordizm\'in "Just-in-Case" (her ihtimale karşı büyük stok tutma) anlayışı ile Post-Fordizm\'in "Just-in-Time" anlayışı karşılaştırıldığında hangisi doğrudur?', 'Fordizm üretimin aksamaması için büyük stoklar tutarken Post-Fordizm stok maliyetini ortadan kaldırmayı hedefler', ['Fordizm yalnızca müşteri siparişi geldikten sonra üretime başlarken Post-Fordizm yıllarca yetecek stok biriktirir', 'Her iki model de tedarik zincirinde hiçbir yan sanayi firmasıyla çalışmayı kabul etmez', 'Post-Fordizm stok maliyetlerini artırmak amacıyla fabrika içinde devasa hammadde depoları kurar'], 'Fordizm\'de hattın durmaması için tampon stoklar tutulurken, JIT sisteminde stok israf sayılarak talep çekişli akış uygulanır.'),
  ('Michael Piore ve Charles Sabel\'in "İkinci Sanayi Bölünmesi" adlı eserlerinde kitle üretimine alternatif olarak kavramsallaştırdıkları model aşağıdakilerden hangisidir?', 'Esnek uzmanlaşma (Flexible specialization)', ['Mutlak vasıfsızlaştırma (Absolute deskilling)', 'Demir kafes rasyonelleşmesi', 'Mekanik işbölümü restorasyonu'], 'Piore ve Sabel, çok amaçlı makineler ve nitelikli işgücüyle değişen pazarlara uyum sağlayan küçük-orta ölçekli ağları "esnek uzmanlaşma" olarak tanımlamıştır.'),
  ('Yalın üretim felsefesinde tüm çalışanların katılımıyla üretim süreçlerinin küçük ama kesintisiz adımlarla sürekli iyileştirilmesini ifade eden Japonca kökenli kavram hangisidir?', 'Kaizen', ['Kanban', 'Zaibatsu', 'Karoshi'], 'Kaizen, yöneticiden işçiye tüm çalışanların katılımıyla süreçlerin sürekli iyileştirilmesi anlamına gelir.'),
  ('Bir fabrikada aynı departmandaki 6-8 işçinin düzenli aralıklarla gönüllü toplanarak üretimdeki kalite sorunlarını tartışıp yönetime çözüm önerileri sunması hangi uygulamaya örnektir?', 'Kalite çemberleri', ['Zaman ve hareket etüdü', 'Sistematik kaytarma', 'Bastırıcı hukuk denetimi'], 'Kalite çemberleri, çalışanların sorun çözme ve kalite geliştirme süreçlerine katılımını sağlayan küçük çalışma gruplarıdır.'),
  ('Fordizm\'den Post-Fordizm\'e geçişte örgüt yapılarında meydana gelen değişim aşağıdakilerden hangisinde doğru verilmiştir?', 'Çok katmanlı dikey hiyerarşilerden daha yatay, ağ tipi ve taşeronlaşmaya açık örgütlenmelere geçilmiştir', ['Küçük ve esnek işletme ağları tasfiye edilerek tek merkezli dev dikey entegre fabrikalara dönülmüştür', 'Tedarik zincirinde dış kaynak kullanımı (outsourcing) bırakılarak her parçanın fabrika içinde üretilmesi benimsenmiştir', 'Takım çalışması ve iş rotasyonu yasaklanarak işçinin tek bir noktada sabitlenmesi kuralı getirilmiştir'], 'Post-Fordizm dikey bürokratik katmanları azaltarak yatay hiyerarşileri, şebeke (ağ) örgütleri ve dış kaynak kullanımını yaygınlaştırmıştır.'),
  ('Bir tekstil markasının tasarımı ve pazarlamayı merkez ofisinde tutup dikim, boyama ve paketleme işlerini farklı ülkelerdeki bağımsız alt yüklenici atölyelere yaptırması hangi kavramla ifade edilir?', 'Dış kaynak kullanımı', ['Dikey Fordist entegrasyon', 'Mekanik köy işbölümü', 'Korumacı lonca tekeli'], 'Ana firmanın çekirdek yetkinlikler dışındaki üretim aşamalarını başka işletmelere devretmesi dış kaynak kullanımıdır.'),
  ('1920\'lerin sonlarında Western Electric şirketinin Hawthorne fabrikasında yürütülen ve çalışma sosyolojisinde "İnsan İlişkileri Okulu"nun doğmasını sağlayan araştırmalara hangi bilim insanı öncülük etmiştir?', 'Elton Mayo', ['Frederick Winslow Taylor', 'Henri Fayol', 'Karl Marx'], 'Elton Mayo ve ekibinin yürüttüğü Hawthorne araştırmaları, verimlilikte biçimsel olmayan grup normlarının ve sosyal ilişkilerin önemini ortaya koymuştur.'),
  ('Çalışma sosyolojisinde "Hawthorne Etkisi" olarak bilinen olgu aşağıdakilerden hangisini açıklar?', 'Çalışanların kendilerine ilgi gösterildiğini ve gözlemlendiklerini fark ettiklerinde performanslarının artması', ['Fabrikadaki aydınlatma düzeyi düşürüldüğünde üretimin her koşulda matematiksel olarak sıfıra inmesi', 'İşçilerin parça başı ücret artışı dışında hiçbir sosyal etkene tepki vermemesi', 'Montaj hattının hızı artırıldığında iş kazalarının kendiliğinden ortadan kalkması'], 'Hawthorne deneylerinde ışıklandırma gibi fiziksel koşullardan ziyade çalışanların önemsenmesi ve gözlemlenme bilincinin verimliliği artırdığı görülmüştür.'),
  ('Bir yazılım şirketinin çekirdek mühendis kadrosunu kadrolu istihdam ederken, test ve veri girişi işlerini proje bazlı kısa süreli sözleşmelerle serbest çalışanlara yaptırması hangi işgücü yapısını örneklendirir?', 'Çekirdek ve çevre (ikili) işgücü piyasası modeli', ['Mekanik dayanışmalı geleneksel lonca modeli', 'Tam istihdamlı ömür boyu Fordist güvence modeli', 'Bürokratik kıdem esasına dayalı memuriyet modeli'], 'Atkinson\'ın esnek firma modelinde nitelikli ve güvenceli çekirdek kadro ile sayısal esnekliğe tabi çevre işgücü bir arada bulunur.'),
  ('İşin tekdüzeliğini kırmak amacıyla çalışanın mevcut yetkinlik düzeyine benzer nitelikteki birkaç ek görevin iş tanımına eklenmesine ne ad verilir?', 'İş genişletme (Job enlargement)', ['İş zenginleştirme (Job enrichment)', 'Bürokratik merkezileşme', 'Taylorist parçalama'], 'Aynı zorluk ve sorumluluk düzeyindeki yatay görevlerin birleştirilerek çeşitlendirilmesi "iş genişletme" olarak tanımlanır.'),
  ('İngiltere\'de kömür madenlerinde yapılan araştırmalar sonucunda örgütlerin hem teknik alt sistem hem de sosyal alt sistemin ortak optimizasyonuyla tasarlanması gerektiğini savunan yaklaşım hangisidir?', 'Sosyo-teknik sistem yaklaşımı (Tavistock Enstitüsü)', ['Saf bilimsel yönetim (Taylorizm)', 'Klasik bürokrasi kuramı', 'Fizyokratik işbölümü okulu'], 'Eric Trist ve Ken Bamforth\'un Tavistock Enstitüsü bünyesindeki maden araştırmaları, teknoloji ile sosyal yapının birlikte uyumlaştırılmasını savunan sosyo-teknik yaklaşımı doğurmuştur.'),
  ('Platform (gig) ekonomisinde çalışan kurye veya sürücülerin çalışma koşullarını denetleyen "algoritmik yönetim" mekanizması sosyolojik olarak nasıl işler?', 'Görev atama, rota çizme, performans puanlama ve yaptırım süreçlerinin müşteri puanları ile yazılımlar üzerinden otomatik yürütülmesiyle', ['Her sabah ustabaşının fabrika kapısında düdük çalarak işçileri tek sıra halinde yoklamaya almasıyla', 'Lonca şeyhinin çıraklara geleneksel el sanatlarının sırlarını sözlü törenle aktarmasıyla', 'Çalışanların hiçbir performans ölçümüne tabi tutulmadan sabit memur maaşı almasıyla'], 'Algoritmik yönetimde gözetim ve disiplin, doğrudan insan amirler yerine veri toplayan yazılımlar ve müşteri değerlendirme puanları üzerinden gerçekleşir.'),
  ('Post-Fordist çalışma ilişkilerinde işverenlerin işgücü maliyetlerini esnekleştirmek amacıyla çalışanların ücretlerini sabit maaş yerine prim, ikramiye ve bireysel performansa endekslemesi hangi esneklik türüdür?', 'Ücret esnekliği', ['Mekanik dayanışma esnekliği', 'Bürokratik kıdem garantisi', 'Geleneksel lonca narhı'], 'Ücretlerin toplu standartlar yerine işletme kârlılığı ve bireysel performansa göre değişken kılınması ücret (finansal/mali) esnekliğidir.'),
  ('Fordist dönemden Post-Fordist döneme geçilirken Batı ülkelerinde ve küresel ölçekte sendikalaşma oranlarının gerilemesinde aşağıdakilerden hangisi etkili olmuştur?', 'Sanayi istihdamından hizmet sektörüne geçiş, esnek/atipik istihdam biçimlerinin ve küçük ölçekli işyerlerinin yaygınlaşması', ['Büyük ölçekli entegre fabrikalarda tek tip kadrolu mavi yakalı işçi sayısının hızla artması', 'Tüm ülkelerde toplu iş sözleşmesi yapma yetkisinin yalnızca işçi sendikalarına devredilmesi', 'Kısmi süreli ve taşeron çalışmanın yasaklanarak ömür boyu iş güvencesinin zorunlu kılınması'], 'Büyük sanayi tesislerindeki homojen işçi kitlesinin parçalanması, hizmet sektörünün büyümesi ve güvencesiz/esnek istihdam sendikal örgütlenmeyi zorlaştırmıştır.'),
  ('Bir çağrı merkezi çalışanının hafta içi yalnızca yoğun saatler olan 12.00-16.00 arasında düzenli olarak haftada 20 saat çalışması hangi atipik istihdam biçimine girer?', 'Kısmi süreli (Part-time) çalışma', ['Tam süreli Fordist vardiyalı çalışma', 'Zorunlu mevsimlik tarım işçiliği', 'Ömür boyu kadrolu memuriyet'], 'Normal haftalık çalışma süresinden önemli ölçüde daha az süreyle düzenli olarak yürütülen istihdam kısmi süreli (part-time) çalışmadır.'),
  ('"Sanayi Sonrası Toplumun Gelişi" (The Coming of Post-Industrial Society) adlı eseriyle bilgi sınıfının ve hizmet ekonomisinin yükselişini inceleyen sosyolog kimdir?', 'Daniel Bell', ['Émile Durkheim', 'Auguste Comte', 'Vilfredo Pareto'], '1973 tarihli bu ünlü eseriyle sanayi sonrası toplum kavramını sosyoloji literatürüne yerleştiren düşünür Daniel Bell\'dir.'),
  ('Toyota üretim sisteminde "otonomasyon" (Jidoka) ilkesi üretim hattındaki işçiye hangi önemli yetkiyi tanıyarak klasik Fordizm\'den ayrılır?', 'Üretimde bir hata veya kalite sorunu fark ettiğinde hattı durdurma (andon ipini çekme) yetkisini', ['Fabrikanın yıllık bilançosunu tek başına onaylayıp hissedarlara kâr dağıtma yetkisini', 'Kusurlu parçaları hiç düzeltmeden doğrudan müşteriye sevk etme yetkisini', 'Mesai saatlerini yönetime haber vermeksizin dilediği gibi kısaltma yetkisini'], 'Fordizm\'de hattı durdurmak kesinlikle yasakken, Jidoka ilkesinde hatanın sonraki aşamaya geçmemesi için işçiye hattı durdurma sorumluluğu verilir.'),
  ('Klasik yönetim düşüncesinde Taylor atölye düzeyinde işin bilimsel analizine odaklanırken, işletmenin bütününü "planlama, örgütleme, yöneltme, eşgüdüm ve denetim" işlevleriyle ele alan Fransız yönetim kuramcısı kimdir?', 'Henri Fayol', ['Elton Mayo', 'Robert Blauner', 'Arlie Hochschild'], 'Genel ve Endüstriyel Yönetim eseriyle üst yönetim süreçlerini ve 14 yönetim ilkesini sistemleştiren düşünür Henri Fayol\'dur.'),
  ('Bir fast-food zincirinde patates kızartma süresinin otomatik fritöz ziliyle belirlenmesi, porsiyon gramajının standart olması ve dünyanın her şubesinde aynı tadın sunulması hangi sosyolojik kavramla açıklanır?', 'McDonaldlaşma', ['Organik meslek loncası', 'Zoraki işbölümü', 'Patrimonyal bürokrasi'], 'Hesaplanabilirlik, öngörülebilirlik ve otomatik teknolojiyle insan hatasının dışlanması Ritzer\'in McDonaldlaşma tezinin doğrudan uygulamasıdır.'),
  ('Adam Smith\'in "Ulusların Zenginliği" eserindeki ünlü toplu iğne fabrikası örneğinde teknik işbölümünün verimliliği büyük ölçüde artırması hangi üç nedene bağlanır?', 'İşçinin el becerisinin artması, işten işe geçerken kaybedilen zamanın önlenmesi ve işi kolaylaştıran makinelerin icadı', ['İşçilerin çalışma saatlerinin günde 18 saate çıkarılması, ücretlerin kesilmesi ve sendikaların kapatılması', 'Ustaların tüm üretim aşamalarını tek başına üstlenerek sanatsal tatmin yaşaması', 'Fabrikada hammadde kullanımının azaltılarak yalnızca ithal bitmiş ürünlerin paketlenmesi'], 'Smith verimlilik artışını el yatkınlığı kazanılması, görev değişimindeki zaman kaybının kalkması ve uzmanlaşmanın makineleşmeyi kolaylaştırmasıyla açıklar.'),
  ('Bir otomotiv fabrikasında standart kitle üretimi yerine bilgisayar destekli üretim (CAD/CAM) tezgâhlarının hızla yeniden programlanarak aynı gün içinde üç farklı model için parça üretilmesi hangi dönemin özelliğidir?', 'Post-Fordist esnek üretim dönemi', ['Erken Fordist tek model dönemi', 'Klasik Taylorist el aleti dönemi', 'Orta Çağ zanaat loncası dönemi'], 'Programlanabilir çok amaçlı makinelerle düşük geçiş maliyetiyle farklı modeller üretebilme Post-Fordist esnek üretimin temel teknik özelliğidir.'),
  ('Taylorizm ve Fordizm\'de işçi denetimi ağırlıklı olarak doğrudan gözetim ve montaj hattının mekanik hızıyla (teknik denetim) sağlanırken, çağdaş kurumsal şirketlerde "normatif/kültürel denetim" nasıl işler?', 'Çalışanların kurum kültürünü, değerlerini ve misyonunu içselleştirerek kendi kendilerini denetlemelerinin teşvik edilmesiyle', ['Ofis koridorlarına hareketli demir zincirler döşenerek memurların masaya kilitlenmesiyle', 'Çalışanların okuma yazma öğrenmesinin engellenerek yalnızca sözlü emirlerle yönetilmesiyle', 'Tüm beyaz yakalı personelin maaşlarının kaldırılıp günlük erzak karnesiyle ödüllendirilmesiyle'], 'Richard Edwards ve Gideon Kunda gibi araştırmacıların belirttiği üzere kurumsal kültür yönetimi, çalışanın örgüt hedefleriyle özdeşleşmesini sağlayarak içsel denetim üretir.'),
  ('Ravenstein\'ın göç yasalarına göre kırsaldan büyük bir sanayi merkezine yönelen göç hareketleri çoğunlukla nasıl gerçekleşir?', 'Kısa mesafeli aşamalarla', ['Doğrudan en uzak metropole', 'Yalnızca sınır ötesi rotalarla', 'Sadece yaşlı nüfus hareketiyle'], 'Ravenstein, göçmenlerin önce yakındaki küçük kasabalara, oradan giderek daha büyük kentlere basamaklı biçimde göç ettiğini gözlemlemiştir.'),
  ('Bir metropolde aynı anda hem yüksek vasıflı göçmenlerin kente gelmesi hem de kentin bazı yerlilerinin yakın kasabalara taşınması Ravenstein\'ın hangi yasasını destekler?', 'Her göç dalgası ters akım doğurur', ['Kadınlar yalnızca uzun mesafeye göç eder', 'Göç hareketi teknolojiyle tamamen durur', 'Kırsal kesim kentten daha az göç verir'], 'Ravenstein\'ın karşı akım yasasına göre her ana göç akımı, farklı nedenlerle ters yönde işleyen bir karşı göç akımı üretir.'),
  ('İş bulmak için başka bir ülkeye gitmek isteyen bir mühendisin yüksek vize ücretleri, dil sınavı şartı ve uzun mesafe yüzünden kararını ertelemesi Lee\'nin kuramında neye örnektir?', 'Araya giren engeller', ['Hedef bölgedeki itici etmen', 'Kaynak yerdeki çekici etmen', 'Geri dönüş göçü mekanizması'], 'Everett Lee\'nin modelinde ulaşım maliyeti, yasal kısıtlamalar ve sınır politikaları kaynak ile hedef arasındaki engelleri oluşturur.'),
  ('Şikago Okulu sosyologlarından Ernest Burgess\'in "Eş Merkezli Bölgeler Kuramı"na göre kent merkezindeki iş bölgesini hemen çevreleyen ve sık nüfus devir hızına sahip kuşak hangisidir?', 'Geçiş bölgesi', ['Üst sınıf banliyö kuşağı', 'Tek aileli konut kuşağı', 'Banliyö taşıtları dış halkası'], 'Burgess\'in modelinde merkezi iş alanının hemen dışındaki geçiş bölgesi, düşük kiralı eski binalar ve yeni göçmenlerin yerleşimiyle karakterizedir.'),
  ('Georg Simmel\'in "Metropol ve Zihinsel Yaşam" incelemesinde büyük kent sakinlerinin aşırı uyaran bombardımanından korunmak için geliştirdiği duygusal mesafe ve kayıtsızlık hali nedir?', 'Bıkkın tutum', ['Organik dayanışma bilinci', 'Kolektif bilinç yoğunluğu', 'Geleneksel cemaat bağlılığı'], 'Simmel, metropoldeki sürekli uyarıcılara karşı bireyin ruhsal bütünlüğünü korumak için hesapçı ve bıkkın (blasé) bir tutum geliştirdiğini savunur.'),
  ('Bir kentte eski bir fabrika bölgesinin sanat galerileri ve lüks kafelere dönüştürülmesinin ardından mahalledeki kiracı esnafın yüksek kira nedeniyle ilçeyi terk etmesi hangi ikili sonucu gösterir?', 'Mekânsal yenilenme ile yerinden edilme', ['Kırsal çözülme ile tarımsal kalkınma', 'Nüfus artışı ile konut bolluğu', 'Kentlileşme ile sosyal eşitlik'], 'Soylulaştırma fiziksel mekânı yenilerken arazi değerini yükselttiği için düşük gelirli eski kullanıcıların yerinden edilmesine yol açar.'),
  ('Hemşehri derneklerinin kente yeni göç eden bireyler için iş bulma, barınma ve sosyal destek sağlarken aynı zamanda kendi içine kapalı ilişki ağları kurması hangi kavramla tartışılır?', 'Tampon mekanizma', ['Mutlak asimilasyon aracı', 'Zorunlu göç politikası', 'Soylulaştırma aktörü'], 'Türk kent sosyolojisinde Mübeccel Kıray, tampon mekanizmaların kırsaldan kente geçişte bunalımı hafifleten geçici toplumsal kurumlar olduğunu belirtmiştir.'),
  ('Doğduğu köydeki düşük tarım gelirinden rahatsız olan ancak ailesinden ayrılmak istemediği için göç etmeyen bir gencin durumu Everett Lee\'nin modelinde hangi ögeyi vurgular?', 'Kişisel etmenler', ['Hedef yerin itici koşulları', 'Resmî vize kısıtlamaları', 'Küresel iş bölümü yapısı'], 'Lee\'ye göre aynı itici ve çekici faktörler karşısında bireylerin yaşı, medeni durumu ve duygusal bağları göç kararını farklılaştırır.'),
  ('Büyük kentlerin etrafındaki küçük kent ve kasabaları içine alarak oluşturduğu, birbirine işlevsel olarak bağlı çok merkezli dev kentsel yığılma bölgelerine ne ad verilir?', 'Megalopol', ['Geleneksel kasaba merkezi', 'Kapalı tarım yerleşimi', 'Kırsal geçiş bölgesi'], 'Jean Gottmann tarafından kavramsallaştırılan megalopol, birden çok metropolün ulaşım ve ekonomi ağlarıyla birleştiği devasa kentsel koridordur.'),
  ('Göçmen bir topluluğun ev sahibi ülkede kendi dilinde gazeteler çıkarıp kültürel bayramlarını kutlaması, ancak aynı zamanda yerel siyasete ve iş yaşamına aktif biçimde katılması hangi modele yakındır?', 'Çok kültürlü entegrasyon', ['Tam kültürel asimilasyon', 'Zorunlu mekânsal ayrışma', 'Geçici mevsimlik göç modeli'], 'Çok kültürlü entegrasyon, grupların kendi kültürel kimliklerini yaşatırken ortak kamusal yaşama eşit katılımını öngörür.'),
  ('İkili işgücü piyasası kuramına göre gelişmiş ülkelerin sürekli göçmen emeğine ihtiyaç duymasının temel nedeni aşağıdakilerden hangisidir?', 'İkincil sektördeki düşük statülü işlerin yerli işgücünce reddedilmesi', ['Gelişmiş ülkelerde üniversite mezunu sayısının hızla düşmesi', 'Kırsal kesimdeki tarım arazilerinin sürekli genişleme göstermesi', 'Uluslararası sınır kontrollerinin bütünüyle ortadan kalkması'], 'Michael Piore\'nin ikili işgücü piyasası kuramına göre gelişmiş ekonomilerdeki güvencesiz, ağır ve düşük prestijli işler yapısal olarak göçmen emeği talep eder.'),
  ('Bir ülkede yurt dışına giden nitelikli bilim insanlarının yıllar sonra edindikleri bilgi ve sermayeyle ülkelerine dönerek teknoloji girişimleri kurmaları hangi kavramla tanımlanır?', 'Tersine beyin göçü', ['Zincirleme aile göçü', 'Zorunlu nüfus mübadelesi', 'İç göç dalgası hareketi'], 'Tersine beyin göçü, yurt dışında deneyim kazanan nitelikli uzmanların köken ülkelerine geri dönerek bilgi ve sermaye aktarmasıdır.'),
  ('Yeni göç ekonomisi kuramı, göç kararını tekil bireyin rasyonel fayda hesabından ziyade hangi birimin risk dağıtma stratejisi olarak görür?', 'Hanehalkının ortak kararı', ['Yalnızca devletin iskân planı', 'Küresel bankaların kredi politikası', 'Tek başına göçmenin kişisel kararı'], 'Yeni göç ekonomisi yaklaşımına göre aileler, gelir riskini çeşitlendirmek amacıyla üyelerinden birini başka bir bölgeye veya ülkeye gönderir.'),
  ('Kentin dış çeperlerinde yüksek duvarlarla çevrili, özel güvenlikli ve kendi sosyal tesislerine sahip lüks konut sitelerinin yaygınlaşması kent sosyolojisinde hangi soruna işaret eder?', 'Mekânsal ayrışma ve kamusal alan daralması', ['Kentsel altyapı giderlerinin tamamen sıfırlanması', 'Toplumsal tabakalar arası kaynaşmanın artması', 'Kent merkezindeki tarihsel dokunun hızla yayılması'], 'Kapalı siteler üst ve orta sınıfları kentin diğer kesimlerinden yalıtarak toplumsal temasın ve kamusal mekân paylaşımının zayıflamasına yol açar.'),
  ('Göçmenlerin hem köken ülkeleriyle hem de yerleşdikleri ülkeyle eş zamanlı ekonomik, kültürel ve sosyal bağlar kurarak iki toplum arasında köprü oluşturması ne ad alır?', 'Ulusötesicilik', ['Tek yönlü asimilasyon', 'Kırsal çözülme süreci', 'Yerel tecrit yaklaşımı'], 'Ulusötesicilik, modern iletişim ve ulaşım olanakları sayesinde göçmenlerin geldikleri ve yaşadıkları ülkelerle sürekli etkileşim içinde kalmasıdır.'),
  ('Ravenstein\'ın yasalarına göre sanayi ve ticaret merkezlerinin büyümesiyle birlikte göç hareketlerinin hacmi nasıl bir eğilim gösterir?', 'Ulaşım ve sanayi geliştikçe göç hacmi artar', ['Ulaşım geliştikçe göç hareketleri tamamen sona erer', 'Sanayileşme yalnızca kırdan kıra göçü teşvik eder', 'Ticaretin artması büyük kentlerin nüfusunu azaltır'], 'Ravenstein, ulaşım araçlarının gelişmesi ve sanayinin genişlemesinin insan hareketliliğini ve göç hacmini sürekli artırdığını belirtmiştir.'),
  ('Homer Hoyt tarafından geliştirilen ve kentsel arazi kullanımının ana ulaşım koridorları boyunca dilimler halinde geliştiğini savunan kent modeli hangisidir?', 'Sektör kuramı', ['Eş merkezli bölgeler kuramı', 'Çok çekirdekli kent kuramı', 'Merkezi yerler hiyerarşisi'], 'Homer Hoyt\'un sektör (dilim) kuramına göre benzer gelir grupları ve sanayi alanları, demiryolu ve ana yollar boyunca kama biçiminde yayılır.'),
  ('Kent içi ulaşımda otoyolların genişlemesiyle birlikte fabrika, üniversite ve alışveriş merkezlerinin tek bir merkez yerine kentin farklı noktalarında kendi odaklarını oluşturması hangi modele uyar?', 'Çok çekirdekli kuram', ['Eş merkezli halkalar modeli', 'Geleneksel kale kenti modeli', 'Tek merkezli tarım yerleşimi'], 'Chauncy Harris ve Edward Ullman\'ın çok çekirdekli kuramı, modern kentlerin tek bir merkezi iş alanı yerine birden çok işlevsel odak etrafında geliştiğini açıklar.'),
  ('Göç süreçlerinde göçmenlerin hedef ülkede çalışıp köken ülkedeki ailelerine düzenli olarak gönderdikleri para transferleri göç literatüründe ne ad alır?', 'İşçi dövizi', ['Dış borçlanma fonu', 'Kentsel rant vergisi', 'İhracat sübvansiyonu'], 'İşçi dövizleri (remittances), göç veren ülkelerdeki hanelerin geçimine ve ulusal ekonomiye önemli döviz girdisi sağlayan transferlerdir.'),
  ('Bir kentte nüfusun kent merkezinden yakın kırsal kasabalara ve köylere doğru tersine hareket etmesi, ancak bu kişilerin kentteki işlerine günlük olarak gidip gelmeye devam etmesi hangi olgudur?', 'Karşı kentleşme', ['Aşırı kentleşme süreci', 'Gecekondulaşma hareketi', 'Soylulaştırma politikası'], 'Karşı kentleşme, özellikle gelişmiş ülkelerde kent yoğunluğundan kaçan nüfusun ulaşım ve uzaktan çalışma olanaklarıyla kırsal çeperlere yerleşmesidir.'),
  ('Louis Wirth\'e göre büyük kentlerde nüfus yoğunluğu ve toplumsal çeşitliliğin artması kişiler arası ilişkilerde nasıl bir dönüşüme yol açar?', 'Birincil bağların zayıflayıp ikincil ilişkilerin artması', ['Akrabalık ilişkilerinin kentin tüm kurumlarına hâkim olması', 'Toplumsal iş bölümünün tamamen ortadan kalkması', 'Bireyler arasında mutlak kültürel homojenlik oluşması'], 'Wirth, kent yaşamında yüz yüze ve samimi birincil bağların yerini yüzeysel, geçici ve işlevsel ikincil ilişkilere bıraktığını savunur.'),
  ('İklim değişikliği nedeniyle yaşanan uzun süreli kuraklık ve deniz seviyesinin yükselmesi sonucunda verimli topraklarını kaybederek göç etmek zorunda kalan topluluklar hangi kavramla anılır?', 'İklim göçmeni', ['Gönüllü iş göçmeni', 'Nitelikli beyin göçmeni', 'Mübadele nüfus grubu'], 'Çevresel bozulma, kuraklık ve taşkın gibi iklim kaynaklı zorlayıcı etmenlerle yer değiştiren kişiler iklim göçmeni olarak adlandırılır.'),
  ('Bir kentin merkezindeki kamu arazilerinin ve parklarının yüksek kâr getiren alışveriş merkezlerine dönüştürülmesi eleştirel kent sosyolojisinde hangi kavramla incelenir?', 'Kentsel mekânın metalaşması', ['Toplumsal dayanışma artışı', 'Kırsal nüfusun dengelenmesi', 'Kültürel entegrasyon süreci'], 'Eleştirel kent sosyologlarına göre kentsel mekânın kullanım değerinden çok değişim değerine ve sermaye birikimine açılması mekânın metalaşmasıdır.'),
  ('Göç sosyolojisinde "döngüsel göç" kavramı aşağıdaki hareket biçimlerinden hangisini tanımlar?', 'Kaynak ve hedef yer arasında tekrarlanan düzenli gidiş gelişler', ['Bir kez yapılan ve geri dönüşü olmayan kalıcı yerleşme', 'Devletler arası anlaşmayla yürütülen zorunlu nüfus değişimi', 'Savaş nedeniyle sığınma talebiyle yapılan tek yönlü göç'], 'Döngüsel göç, işçilerin veya uzmanların belirli aralıklarla hedef ülke ile köken ülke arasında düzenli biçimde hareket etmesidir.'),
  ('İkinci kuşak göçmen gençlerin hem ailelerinin köken kültürüyle hem de doğdukları ülkenin kültürel beklentileriyle çelişkiler yaşaması sosyolojide hangi kavramla ilişkilendirilir?', 'Kültürel arada kalmışlık', ['Mutlak coğrafi tecrit', 'Tek yönlü kırsal çözülme', 'Tam demografik homojenlik'], 'Kuşaklar arası göç deneyiminde ikinci kuşak, aile içi geleneksel normlar ile okul ve arkadaş çevresindeki ev sahibi toplum normları arasında kimlik gerilimi yaşayabilir.'),
  ('Göçmenlerin yeni yerleştikleri kentte kendi hemşehrilerinin yoğun olduğu mahallelerde toplanarak dil, iş ve barınma ağı oluşturmaları hangi mekânsal yapıyı doğurur?', 'Etnik yerleşim bölgesi', ['Merkezi finans bölgesi', 'Ağır sanayi üretim kuşağı', 'Üst sınıf tatil banliyösü'], 'Etnik yerleşim bölgeleri (enklavlar), göçmenlere ilk uyum aşamasında iş, dayanışma ve kültürel devamlılık imkânı sunar.'),
  ('Kent içi gecekondu mahallelerinin belediye ve özel sektör iş birliğiyle yıkılıp yerine çok katlı modern konutların yapılması sürecine ne ad verilir?', 'Kentsel dönüşüm', ['Kırsal kalkınma planı', 'Karşı kentleşme akımı', 'Mevsimlik iskân hareketi'], 'Kentsel dönüşüm, çöküntü veya afet riski taşıyan kentsel alanların planlı biçimde yenilenmesi ve yeniden yapılandırılmasıdır.'),
  ('Göç kuramlarından "göç ağları yaklaşımı"na göre bir göç akımı başladıktan sonra ekonomik koşullar değişse bile göçün sürmesinin temel sebebi nedir?', 'Akrabalık ve hemşehrilik bağlarının göç riskini azaltması', ['Hedef ülkede ücretlerin sürekli düşüş göstermesi', 'Kaynak ülkede işsizliğin tamamen ortadan kalkması', 'Ulaşım maliyetlerinin hızla artış kaydetmesi'], 'Göç ağları kuramına göre kurulan toplumsal bağlar bilgi, konaklama ve iş bulma desteği sağlayarak göçü kendi kendini besleyen bir sürece dönüştürür.'),
  ('Bir ülkede büyük kentlerde yaşayan nüfusun toplam nüfusa oranı hızla yükseldiği halde kentlerdeki bireylerin geleneksel kırsal dayanışma ve değer kalıplarını sürdürmesi hangi durumu gösterir?', 'Kentleşmenin kentlileşmeden hızlı ilerlemesi', ['Kentlileşmenin kentleşmeden önce tamamlanması', 'Kırsal kesimde sanayileşmenin aşırı artması', 'Büyük kentlerin nüfus kaybetmeye başlaması'], 'Fiziksel olarak kente yerleşmek kısa sürede gerçekleşebilirken kentsel kültür ve değerleri içselleştirmek anlamına gelen kentlileşme daha uzun sürer.'),
  ('Uluslararası göç hukukunda ülkesinden ayrılıp başka bir ülkeye koruma talebiyle başvuran ancak mülteci statüsü başvurusu henüz sonuçlanmamış kişiye ne denir?', 'Sığınmacı', ['Düzenli işçi göçmen', 'Kalıcı vatandaş adayı', 'Mevsimlik tarım işçisi'], 'Sığınmacı, mülteci olarak tanınma talebinde bulunmuş fakat hukuki statü değerlendirme süreci henüz tamamlanmamış kişidir.'),
  ('Sanayi sonrası dönemde büyük fabrikaların kent merkezlerinden çevre bölgelere veya başka ülkelere taşınmasıyla merkezde işsizliğin artması ve mahallelerin çöküntü alanına dönüşmesi ne ad alır?', 'Sanayisizleşme ve kentsel çöküş', ['Aşırı tarımsal makineleşme', 'Kırsal dönüşüm ve iskân', 'Dengeli metropoliten genişleme'], 'Sanayisizleşme, imalat sanayisinin kentten çekilmesiyle eski işçi mahallelerinde ekonomik gerileme ve mekânsal bozulma yaratır.'),
  ('Bir bireyin kendi isteği dışında savaş, doğal afet, baraj yapımı veya siyasi baskı gibi nedenlerle yaşadığı yeri terk etmek zorunda kalmasına ne denir?', 'Zorunlu göç', ['Gönüllü iş göçü', 'Eğitim amaçlı göç', 'Döngüsel emek göçü'], 'Zorunlu göçte yer değiştirme kararı bireyin refah arayışından değil, can güvenliği veya yaşam alanının kaybından kaynaklanır.'),
  ('Büyük bir liman kentinde tarihsel olarak ticaretin yapıldığı sahil şeridinin depo ve iskelelerden arındırılarak müze, yat limanı ve lüks restoranlara dönüştürülmesi hangi kentsel stratejiye örnektir?', 'Kültür odaklı kentsel canlandırma', ['Ağır sanayi yoğunlaştırma planı', 'Kırsal tarım alanlarını genişletme', 'Gecekondu bölgelerini yasallaştırma'], 'Sanayi sonrası kentler, eski liman ve üretim alanlarını turizm, kültür ve tüketim odaklı projelerle yeniden değerlendirme yoluna gider.'),
  ('Göçmenlerin yerleştiği ülkede yasal ikamet veya çalışma izni olmaksızın bulunması ya da sınır geçişlerini yasal prosedürler dışında gerçekleştirmesi hangi kavramla ifade edilir?', 'Düzensiz göç', ['Planlı işgücü göçü', 'İkili anlaşmalı mübadele', 'Akademik değişim programı'], 'Düzensiz göç, kaynak, transit veya hedef ülkenin yasal düzenlemeleri dışında gerçekleşen giriş, ikamet ya da çalışma hareketleridir.'),
  ('Kent sosyolojisinde Robert Ezra Park\'ın kenti bir "toplumsal laboratuvar" olarak tanımlamasının temel nedeni aşağıdakilerden hangisidir?', 'Farklı toplumsal süreçlerin ve insan doğasının kentte yoğun biçimde gözlemlenebilmesi', ['Kentlerin yalnızca doğa bilimleri yöntemleriyle incelenebilmesi', 'Kırsal kesimde hiçbir toplumsal etkileşimin gerçekleşmemesi', 'Kent yaşamının tarih boyunca hiç değişmeden sabit kalması'], 'Şikago Okulu öncüsü Robert Park, göç, rekabet, uyum ve ayrışma gibi toplumsal süreçlerin en belirgin biçimde modern metropollerde gözlemlenebileceğini savunmuştur.'),
  ('Demografik dönüşümün üçüncü aşamasında doğum oranlarının belirgin biçimde düşmeye başlamasında aşağıdaki sosyolojik etmenlerden hangisi en güçlü rolü oynar?', 'Kentleşme, kadınların eğitim ve istihdama katılımının artması', ['Tarımsal üretimin tek geçim kaynağı haline gelmesi', 'Sağlık hizmetlerinin ve aşı programlarının durdurulması', 'Çocuk işçiliğinin aile geliri için zorunlu hale gelmesi'], 'Üçüncü aşamada kentleşme, kadınların işgücüne katılması, eğitim süresinin uzaması ve çocuk yetiştirme maliyetlerinin artması doğurganlığı düşürür.'),
  ('Bir ülkede çalışma çağındaki nüfusun (15-64 yaş) toplam nüfus içindeki payının geçici olarak çok yükselmesi ve bağımlılık oranının düşmesi sonucu ortaya çıkan kalkınma potansiyeline ne ad verilir?', 'Demografik fırsat penceresi', ['Demografik kriz ve daralma', 'Yaşlı bağımlılık çıkmazı', 'Kırsal nüfus patlaması dönemi'], 'Doğurganlığın düşmeye başlamasıyla çocuk bağımlılığı azalırken yaşlı nüfus henüz çok artmadığı için oluşan üretken nüfus ağırlıklı döneme demografik fırsat penceresi denir.'),
  ('Arı kovanı biçiminde, tabanı daralmış ancak orta ve üst yaş grupları geniş bir nüfus piramidine sahip ülkenin karşılaşması en olası sosyal politika sorunu nedir?', 'Emeklilik ve yaşlı bakım sistemlerinin finansman baskısı', ['İlkokul çağındaki öğrenci sayısının aşırı patlaması', 'Genç işgücü fazlalığından doğan tarım arazisi kıtlığı', 'Ortalama yaşam beklentisinin kırk yaşın altına inmesi'], 'Yaşlanan nüfuslu ülkelerde çalışan başına düşen emekli sayısı arttığı için sosyal güvenlik, emeklilik maaşları ve sağlık bakımı üzerinde ciddi mali yük oluşur.'),
  ('Fordist üretim sistemi ile sosyal refah devleti arasındaki tarihsel bağ çalışma sosyolojisinde nasıl açıklanır?', 'Kitlesel üretimin sürmesi için işçilere düzenli ücret ve tüketim gücü sağlanmasıyla', ['Devletin tüm fabrikaları kapatarak tarımsal üretime dönmesiyle', 'İşçilerin ücretlerinin sürekli düşürülerek tüketimin kısıtlanmasıyla', 'Sendikaların yasaklanıp tüm çalışma saatlerinin sınırsız bırakılmasıyla'], 'Fordizm, yüksek verimlilikle üretilen standart malların satılabilmesi için görece yüksek ücret, tam istihdam ve sosyal güvenlik sunan Keynesyen refah devletiyle bütünleşmiştir.'),
  ('Karl Marx\'ın yabancılaşma çözümlemesine göre bir montaj hattı işçisinin gün boyu yalnızca tek bir vidayı sıkması ve ortaya çıkan otomobil üzerinde hiçbir söz hakkı olmaması hangi yabancılaşma boyutlarını doğrudan örneklendirir?', 'Üretim sürecine ve ürüne yabancılaşma', ['Yalnızca coğrafi mekâna yabancılaşma', 'Sadece geleneksel tarım kültürüne yabancılaşma', 'Kentsel tüketim alışkanlıklarına yabancılaşma'], 'İşçinin çalışma biçimini belirleyememesi üretim sürecine, ürettiği nesnenin kendine ait olmaması ise ürüne yabancılaşmayı gösterir.'),
  ('Bir teknoloji şirketinin yazılım geliştirme departmanını kadrolu tutarken temizlik, yemek ve güvenlik hizmetlerini dışarıdaki başka firmalardan satın alması Postfordist hangi uygulamadır?', 'Taşeronlaştırma', ['Dikey tam entegrasyon', 'Klasik lonca örgütlenmesi', 'Ömür boyu tek iş yeri garantisi'], 'Postfordist esneklik stratejilerinden biri olan taşeronlaştırma (dış kaynak kullanımı), çekirdek olmayan işlerin alt işverenlere devredilerek maliyetlerin düşürülmesidir.'),
  ('Kayıt dışı istihdamın yüksek olduğu bir ekonomide hem çalışanlar hem de devlet açısından ortaya çıkan temel ortak sonuç aşağıdakilerden hangisidir?', 'Çalışanlar sosyal güvenceden, devlet ise vergi ve prim gelirinden mahrum kalır', ['İşçiler daha yüksek emeklilik maaşı alırken kamu bütçesi fazla verir', 'Sendikal örgütlenme güçlenerek iş sağlığı standartları zirveye çıkar', 'İşgücü piyasasında ücret eşitsizliği kendiliğinden tamamen ortadan kalkar'], 'Kayıt dışı çalışma, işçiyi emeklilik, işsizlik sigortası ve iş güvenliğinden yoksun bırakırken devletin sosyal güvenlik prim ve vergi tabanını aşındırır.'),
  ('Çalışma sosyolojisinde Harry Braverman\'ın "vasıfsızlaştırma" tezi, Taylorist yönetim tekniklerinin işçinin emeği üzerindeki hangi etkisini vurgular?', 'Zihinsel planlamayı el emeğinden ayırarak işçinin iş üzerindeki ustalığını azaltmasını', ['Her işçinin üretim sürecinin tüm aşamalarını öğrenerek çok yönlü uzmanlaşmasını', 'Otomasyon sayesinde çalışma saatlerinin tüm sektörlerde yarıya indirilmesini', 'Zanaatkârların fabrika yönetiminde tek karar verici konuma yükselmesini'], 'Braverman, Taylorizmin işi parçalara bölüp bilgiyi yönetimde toplamasının, işçiyi kolayca ikame edilebilir vasıfsız bir uygulayıcıya dönüştürdüğünü savunmuştur.'),
  ('Doğum oranlarının uzun süre yenilenme düzeyinin altında kalması nedeniyle toplam nüfusu azalmaya başlayan bir ülke demografik dönüşümün hangi aşamasındadır?', 'Beşinci aşama', ['Birinci yüksek denge aşaması', 'İkinci hızlı artış aşaması', 'Üçüncü doğurganlık düşüş aşaması'], 'Bazı demograflarca eklenen beşinci aşamada doğurganlık çok düşük düzeyde seyreder, ölüm oranları yaşlı nüfus payı nedeniyle doğumları aşar ve doğal nüfus azalır.'),
  ('Bir ülkede yükseköğretim mezunu bir mühendisin kendi alanında iş bulamadığı için düşük ücretli bir çağrı merkezinde çalışması işgücü piyasasında hangi kavramla tanımlanır?', 'Eksik istihdam', ['Tam verimli istihdam', 'Yukarı dikey hareketlilik', 'Kayıtlı yüksek uzmanlaşma'], 'Nitelik uyumsuzluğu içeren eksik istihdam, çalışanın eğitim ve beceri düzeyinin çok altında bir işte veya istediğinden daha az saatte çalışmak zorunda kalmasıdır.'),
  ('Postfordist üretimde Japon otomotiv sanayisiyle özdeşleşen ve depolama maliyetini azaltmak için parçaların tam üretim anında tedarik edilmesine dayanan yöntem nedir?', 'Tam zamanında üretim', ['Yığın stoklu seri üretim', 'Sabit kotalı ağır sanayi', 'Geleneksel atölye birikimi'], 'Toyotizm ile yaygınlaşan tam zamanında (Just-in-Time) üretim, büyük stoklar yerine müşteri talebine göre anlık tedarik ve esnek montaj ilkelerine dayanır.'),
  ('Bir toplumda tarımsal istihdamın hızla azalması ve sanayi ile hizmet sektörlerinde milyonlarca yeni iş alanı açılması nedeniyle çiftçi çocuklarının büyük ölçüde teknisyen ve memur olması hangi hareketlilik türüdür?', 'Yapısal hareketlilik', ['Bireysel dolaşım hareketliliği', 'Kuşak içi yatay geçiş süreci', 'Mevsimlik emek hareketliliği'], 'Yapısal hareketlilik, bireysel yetenekten çok ekonomideki sektörel ve mesleki yapının dönüşmesiyle geniş kitlelerin konum değiştirmesidir.'),
  ('Bir şirkette hem çalışanların çalışma saatlerini kendi seçebilmesi hem de haftanın üç günü evden çalışabilmesi hangi esneklik türlerine örnektir?', 'Zaman ve mekân esnekliği', ['Ücret kesintisi ve kayıt dışılık', 'Sayısal işten çıkarma esnekliği', 'Sıkı Taylorist zaman denetimi'], 'Esnek çalışma modelleri içinde çalışma saatlerinin düzenlenmesi zaman esnekliğini, uzaktan veya hibrit çalışma ise mekân esnekliğini oluşturur.'),
  ('Çalışma sosyolojisinde kadınların yoğunlaştığı işlerde terfi olanaklarının yazılı olmayan engellerle sınırlanması ve üst yönetim kademelerine erişimin zorlaşması hangi metaforla açıklanır?', 'Cam tavan', ['Yapışkan iş bölümü', 'Yatay hareketlilik eşiği', 'Mesleki tam bütünleşme'], 'Cam tavan, kadınların ve azınlık gruplarının nitelikli olmalarına rağmen görünmez kurumsal önyargılar nedeniyle üst yönetim pozisyonlarına yükselmelerinin engellenmesidir.'),
  ('Demografik yaşlanma yaşayan bir ülkede yaşlı bağımlılık oranının hızla artması işgücü piyasası üzerinde orta vadede nasıl bir baskı oluşturur?', 'Çalışma çağındaki nüfus daralır ve emeklilik yaşının yükseltilmesi gündeme gelir', ['Genç işgücü bolluğu nedeniyle tüm sektörlerde işsizlik otomatik olarak artar', 'İlkokul öğretmeni ihtiyacı yaşlı bakım personeli ihtiyacını katlayarak aşar', 'Kayıtlı çalışanların sosyal güvenlik prim yükü hızla azalarak sıfırlanır'], 'Yaşlanan toplumlarda aktif çalışan sayısının emekli sayısına oranı düştüğünden, işgücü açığını kapatmak için emeklilik yaşının artırılması veya nitelikli göç politikaları tartışılır.'),
  ('Arlie Hochschild\'in çalışma sosyolojisine kazandırdığı ve özellikle hizmet sektörü çalışanlarının iş gereği sürekli güler yüzlü, sakin ve anlayışlı görünmek zorunda kalmasını anlatan kavram nedir?', 'Duygusal emek', ['Fiziksel montaj emeği', 'Ağır sanayi işgücü', 'Geleneksel tarım emeği'], 'Duygusal emek, çağrı merkezi, havayolu, sağlık ve turizm gibi hizmet işlerinde çalışanların kendi gerçek hislerinden bağımsız olarak işverenin beklediği duyguları sergilemesidir.'),
  ('Bir ülkede son on yılda kaba doğum oranı hızla düşerken aynı dönemde net dış göç alınmıyorsa, önümüzdeki yirmi yıl içinde o ülkenin nüfus piramidinde nasıl bir değişim beklenir?', 'Taban daralırken ortanca yaş ve yaşlı nüfus payı yükselir', ['Taban hızla genişler ve 0-14 yaş grubu nüfusun yarısını aşar', 'Ülkenin toplam bağımlılık oranı aniden sıfıra iner', 'Nüfus piramidi keskin bir üçgen biçimine geri döner'], 'Doğurganlığın düşmesi genç kuşakların payını azaltırken mevcut kuşaklar yaşlandıkça nüfusun ortanca yaşı yükselir ve piramit üst kısma doğru şişkinleşir.'),
  ('Yemek dağıtım ve ulaşım uygulamaları üzerinden bağımsız yüklenici statüsünde çalışan, iş güvenliği ve ücretli izin haklarından yararlanamayan kuryelerin çalışma biçimi hangi kavramla incelenir?', 'Gig ekonomisi', ['Klasik Fordist güvence', 'Kamu memuriyeti rejimi', 'Lonca tipi zanaat sistemi'], 'Dijital platformlar aracılığıyla kısa süreli, görev başına ödemeli ve çoğunlukla sosyal güvencesiz yürütülen çalışma biçimi gig (esnek platform) ekonomisi olarak adlandırılır.'),
  ('Bir işletmede kriz dönemlerinde maliyetleri düşürmek için geçici sözleşmeli işçilerin hızla işten çıkarılıp piyasa canlandığında yeniden işe alınması hangi esneklik stratejisidir?', 'Sayısal esneklik', ['İşlevsel beceri esnekliği', 'Ücret eşitliği politikası', 'Uzun vadeli kariyer garantisi'], 'Sayısal esneklik, işletmelerin talep dalgalanmalarına göre çalışan sayısını belirli süreli, kısmi zamanlı veya geçici sözleşmelerle hızla artırıp azaltabilmesidir.'),
  ('Demografik araştırmalarda nüfusun yarısının altında, yarısının ise üstünde yer aldığı yaş değerini ifade eden ve toplumun gençlik ya da yaşlılık düzeyini özetleyen gösterge nedir?', 'Ortanca yaş', ['Kaba ölüm hızı', 'Doğurganlık yenilenme hızı', 'Genç bağımlılık katsayısı'], 'Ortanca (medyan) yaş yükseldikçe toplumun yaşlandığı, düştükçe nüfusun gençleştiği anlaşılır.'),
  ('Bir otomobil fabrikasında işçilerin tek bir işleme sabitlenmek yerine rotasyonla farklı istasyonlarda çalışabilmesi ve kalite kontrol süreçlerine katılması hangi esneklik türüdür?', 'İşlevsel esneklik', ['Sayısal işten çıkarma esnekliği', 'Kayıt dışı taşeron istihdam', 'Katı Taylorist uzmanlaşma'], 'İşlevsel esneklik, çok yönlü eğitilmiş çalışanların işletme içinde değişen üretim görevlerine ve teknolojik yeniliklere uyum sağlayabilmesidir.'),
  ('Tam zamanlı ve yasal olarak bir işte çalışmasına rağmen elde ettiği ücretle kendisinin ve ailesinin temel yoksulluk sınırının üzerine çıkamayan kesimi tanımlayan kavram nedir?', 'Çalışan yoksullar', ['Yapısal işsizler grubu', 'Üst düzey beyaz yakalılar', 'Mevsimlik gönüllü çalışanlar'], 'Çalışan yoksulluğu, istihdamda olmanın tek başına yoksulluktan kurtulmayı garanti etmediği düşük ücretli ve güvencesiz iş piyasası koşullarını gösterir.'),
  ('Bir ülkede kaba ölüm oranının son yıllarda hafifçe yükselmeye başlaması, sağlık sisteminin çöktüğü anlamına gelmeyip hangi demografik yapı değişikliğinden kaynaklanabilir?', 'Toplam nüfus içinde ileri yaşlı grubun oranının çok yükselmesinden', ['Bebek aşılamalarının ülke genelinde tamamen durdurulmasından', 'Doğum oranlarının iki katına çıkmasından', 'Genç nüfusun çalışma çağına henüz girmemiş olmasından'], 'Çok yaşlı nüfusa sahip gelişmiş ülkelerde sağlık hizmetleri mükemmel olsa bile yaşlı payının fazlalığı nedeniyle kaba ölüm oranı genç nüfuslu ülkelere göre daha yüksek çıkabilir.'),
  ('George Ritzer\'in Max Weber\'in rasyonelleşme kuramını çağdaş hizmet ve çalışma hayatına uyarlayarak verimlilik, hesaplanabilirlik, öngörülebilirlik ve denetim ilkeleriyle açıkladığı kavram nedir?', 'McDonaldlaşma', ['Demografik dönüşüm', 'Kentsel soylulaştırma', 'Kültürel melezleşme'], 'Ritzer\'in McDonaldlaşma tezi, fast-food restoranlarının standartlaşmış, hızlı ve sıkı denetimli iş örgütlenmesinin eğitimden sağlığa kadar tüm çalışma alanlarına yayıldığını savunur.'),
  ('Babasının işçi olarak çalıştığı bir tekstil atölyesinde çocuk yaşta çalışmaya başlayan bir bireyin akşam eğitimiyle üniversiteyi bitirip avukat olması hangi iki kavramla birlikte değerlendirilir?', 'Kuşaklar arası ve kuşak içi yukarı hareketlilik', ['Yalnızca kuşak içi yatay mesleki geçiş', 'Yapısal aşağı doğru sınıf hareketliliği', 'Kayıt dışı mevsimlik işgücü dolaşımı'], 'Bireyin hem babasına göre statü yükseltmesi (kuşaklar arası) hem de kendi çalışma yaşamı içinde yükselmesi (kuşak içi) yukarı dikey hareketliliktir.'),
  ('Demografide bir yılda doğan her 1000 canlı bebekten bir yaşını doldurmadan hayatını kaybedenlerin sayısını gösteren ve ülkelerin gelişmişlik düzeyini hassas biçimde yansıtan ölçüt nedir?', 'Bebek ölüm hızı', ['Toplam doğurganlık oranı', 'Yaşlı bağımlılık oranı', 'Kaba evlenme istatistiği'], 'Bebek ölüm hızı, beslenme, anne sağlığı, temiz su ve sağlık altyapısının kalitesine doğrudan duyarlı olduğu için temel insani gelişmişlik göstergelerindendir.'),
  ('Klasik Fordist fabrikalarda çalışanların büyük çoğunluğu aynı mekânda ve benzer koşullarda çalıştığı için sendikalaşma görece kolayken, Postfordist dönemde sendikalaşma oranlarının gerilemesinde hangisi en etkilidir?', 'İşyerlerinin küçülmesi, taşeronlaşma ve esnek istihdamın yaygınlaşması', ['Tüm ülkelerde imalat sanayisinin tek bir dev fabrikada toplanması', 'Çalışanların tamamının ömür boyu kamu memurluğuna geçirilmesi', 'İletişim teknolojilerinin işçiler arasında haberleşmeyi imkânsız kılması'], 'Üretimin küçük birimlere bölünmesi, geçici sözleşmeler, evden çalışma ve hizmet sektörünün büyümesi klasik kitlesel sendikal örgütlenmeyi zorlaştırmıştır.'),
  ('Çalışma sosyolojisinde hem yüksek nitelikli, güvenceli ve kariyer olanağı sunan işleri hem de düşük ücretli, geçici ve güvencesiz işleri aynı ekonomide barındıran bölünmüş yapıya ne ad verilir?', 'İkili işgücü piyasası', ['Tek tip homojen piyasa', 'Eşitlikçi lonca sistemi', 'Merkezi planlı tam istihdam'], 'İkili işgücü piyasası kuramı, emek piyasasının birincil (güvenceli, yüksek ücretli) ve ikincil (güvencesiz, düşük ücretli) kesimler biçiminde katmanlaştığını vurgular.'),
  ('Bir ülkede doğum hızı hızla düştüğü halde nüfusun birkaç on yıl daha artmaya devam etmesi, önceki yüksek doğurganlık döneminden gelen geniş genç kuşağın üreme çağına girmesiyle açıklanır. Bu olguya ne ad verilir?', 'Demografik ivme', ['Demografik çöküş', 'Yaşlılık durağanlığı', 'Kaba ölüm sapması'], 'Demografik ivme (momentum), doğurganlık yenilenme düzeyine inse bile anne-baba olacak genç nüfus kitlesinin genişliği yüzünden toplam nüfusun bir süre daha büyümeyi sürdürmesidir.'),
  ('Kadınların işgücüne katılım oranlarının artmasına karşın ev içi bakım ve temizlik işlerinin ağırlıklı olarak yine kadınlar tarafından üstlenilmesi sosyolojide hangi kavramla tanımlanır?', 'İkinci vardiya', ['Esnek zaman avantajı', 'Yatay kariyer dengesi', 'Dijital iş bölümü'], 'Arlie Hochschild tarafından kavramsallaştırılan ikinci vardiya, ücretli işte çalışan kadınların eve döndüklerinde ücretsiz ev ve bakım emeğini de sürdürmek zorunda kalmasıdır.'),
  ('İşgücü piyasasında çalışanların bir işten ayrılıp daha uygun yeni bir iş arama sürecinde geçici olarak yaşadıkları kısa süreli işsizlik türüne ne ad verilir?', 'Friksiyonel işsizlik', ['Kronik yapısal işsizlik', 'Gizli tarımsal işsizlik', 'Kalıcı teknolojik işsizlik'], 'Friksiyonel (geçici) işsizlik, iş değiştirme veya mezuniyet sonrası ilk işi arama sürecinde ortaya çıkan doğal ve kısa dönemli işsizliktir.'),
  ('Bir ülkenin demografik fırsat penceresinden ekonomik büyüme elde edebilmesi için çalışma çağındaki genç nüfusun artması tek başına neden yeterli değildir?', 'Nitelikli eğitim ve yeterli istihdam yaratılmazsa genç işsizliği büyür', ['Genç nüfus arttığında tüketim harcamaları kendiliğinden sıfırlanır', 'Çalışma çağındaki nüfusun artması derhal yaşlı nüfusu ortadan kaldırır', 'Demografik fırsat yalnızca tarım toplumlarında geçerli bir kuraldır'], 'Genç ve üretken nüfus yoğunluğu ancak kaliteli eğitim, sağlık yatırımları ve üretken iş alanlarıyla desteklendiğinde ekonomik kalkınmaya dönüşür; aksi halde işsizlik krizi doğurur.'),
  ('Aile işletmelerinde veya kırsal tarımda çalışıyor görünmesine rağmen üretimden çekildiğinde toplam çıktının azalmadığı düşük verimlilikli istihdam biçimi nedir?', 'Gizli işsizlik', ['Sözleşmeli esnek çalışma', 'Mevsimlik tam istihdam', 'Yüksek vasıflı uzmanlık'], 'Gizli işsizlik, marjinal verimliliği sıfıra yakın olan fazla işgücünün özellikle geleneksel tarım veya küçük aile işletmelerinde çalışıyor görünmesidir.'),
  ('Bir sanayi bölgesinde kömür madenlerinin kapanmasıyla işsiz kalan madencilerin, yeni açılan yazılım şirketlerinin aradığı becerilere sahip olmadığı için uzun süre iş bulamaması hangi işsizlik türüdür?', 'Yapısal işsizlik', ['Kısa süreli friksiyonel işsizlik', 'Mevsimlik turizm işsizliği', 'Gönüllü kariyer arası boşluk'], 'Yapısal işsizlik, ekonomideki sektörel ve teknolojik değişimler sonucu işçilerin mevcut becerileri ile piyasanın talep ettiği nitelikler arasında kalıcı uyumsuzluk oluşmasıdır.'),
];
